import type { ExerciseQuestion } from "../types";

export const NOUN_QUESTIONS: ExerciseQuestion[] = [
  { id: "n001", question: "Her _____ to the problem surprised the whole team. (solve)", options: ["solve", "solution", "solvable", "solvingly"], correctIndex: 1, explanation: "'Solution' là danh từ được tạo từ động từ 'solve' bằng hậu tố '-tion'. Sau tính từ sở hữu 'Her' và đứng làm chủ ngữ của câu, chỗ trống cần một danh từ chứ không phải động từ. Đáp án gây nhiễu 'solve' là dạng động từ nguyên mẫu nên không thể đứng ngay sau 'Her'." },
  { id: "n002", question: "Higher _____ leads to better job opportunities. (educate)", options: ["educate", "educated", "educational", "education"], correctIndex: 3, explanation: "'Education' là danh từ của động từ 'educate', tạo bằng hậu tố '-tion'. Đứng sau tính từ 'Higher' và làm chủ ngữ cho động từ 'leads', vị trí này bắt buộc là danh từ. Dễ nhầm với 'educational' - đó là tính từ (hậu tố '-al') nên không thể tự làm chủ ngữ được." },
  { id: "n003", question: "It was a difficult _____ to make. (decide)", options: ["decide", "decisive", "decisively", "decision"], correctIndex: 3, explanation: "'Decision' là danh từ của 'decide' (đổi đuôi thành '-sion'). Sau mạo từ 'a' và tính từ 'difficult', chỗ trống cần danh từ để hoàn chỉnh cụm 'a difficult decision'. Lưu ý 'decisive' là tính từ (nghĩa quyết đoán) nên không thể đứng sau mạo từ 'a' và tính từ ở vị trí danh từ." },
  { id: "n004", question: "His _____ of history is truly impressive. (know)", options: ["know", "knowing", "knowledgeable", "knowledge"], correctIndex: 3, explanation: "'Knowledge' là danh từ bất quy tắc của động từ 'know' (không theo hậu tố thông thường như '-tion' hay '-ment'). Đứng sau sở hữu cách 'His' và làm chủ ngữ, cần một danh từ. 'Knowledgeable' dễ gây nhầm vì nghe học thuật nhưng đó là tính từ (hậu tố '-able', nghĩa 'am hiểu'), không thể làm chủ ngữ." },
  { id: "n005", question: "The _____ of the city has been remarkable. (develop)", options: ["develop", "developer", "developmental", "development"], correctIndex: 3, explanation: "'Development' là danh từ chỉ 'sự phát triển', tạo từ 'develop' bằng hậu tố '-ment'. Đứng sau 'The' và làm chủ ngữ của câu (theo sau là 'of the city'), cần danh từ trừu tượng chỉ quá trình. Tránh nhầm với 'developer' - cũng là danh từ nhưng chỉ người (nhà phát triển), không hợp nghĩa 'sự phát triển của thành phố'." },
  { id: "n006", question: "Good _____ skills are essential for any leader. (manage)", options: ["manage", "managerial", "manageable", "management"], correctIndex: 3, explanation: "'Management' là danh từ của 'manage' (hậu tố '-ment'), dùng làm danh từ ghép đứng trước 'skills' để chỉ 'kỹ năng quản lý'. Vị trí danh từ + danh từ này không chấp nhận tính từ. 'Manageable' là tính từ nghĩa 'có thể quản lý/kiểm soát được', khác hẳn nghĩa cần dùng nên không phù hợp ở đây." },
  { id: "n007", question: "The painting shows great _____. (create)", options: ["create", "creation", "creative", "creativity"], correctIndex: 3, explanation: "'Creativity' là danh từ trừu tượng tạo từ tính từ 'creative' (gốc động từ 'create') bằng hậu tố '-ity', chỉ 'sự sáng tạo'. Sau tính từ 'great' và làm tân ngữ của 'shows', câu cần một danh từ không đếm được. 'Creation' cũng là danh từ nhưng nghĩa là 'tác phẩm/sự tạo ra', không hợp nghĩa bằng 'creativity' ở đây." },
  { id: "n008", question: "The _____ of the factory doubled this year. (produce)", options: ["produce", "product", "productive", "production"], correctIndex: 3, explanation: "'Production' (hậu tố '-tion' từ 'produce') là danh từ chỉ 'sản lượng/quá trình sản xuất', đứng sau 'The' làm chủ ngữ của câu. 'Product' cũng là danh từ nhưng nghĩa là 'sản phẩm' cụ thể, không phải 'sản lượng' nên không khớp nghĩa dù cùng là danh từ." },
  { id: "n009", question: "Congratulations on your _____! (succeed)", options: ["succeed", "successful", "successfully", "success"], correctIndex: 3, explanation: "'Success' là danh từ của động từ 'succeed' (không thêm hậu tố quen thuộc mà đổi hẳn dạng). Sau sở hữu cách 'your' và giới từ 'on', chỗ trống cần danh từ. 'Successful' là tính từ (hậu tố '-ful') nên không thể đứng ngay sau 'your' ở vị trí danh từ được." },
  { id: "n010", question: "Every _____ teaches us something valuable. (fail)", options: ["fail", "failure", "failed", "failing"], correctIndex: 1, explanation: "'Failure' là danh từ đếm được của 'fail', tạo bằng hậu tố '-ure', nghĩa 'thất bại'. Sau từ chỉ định lượng 'Every' luôn cần danh từ số ít làm chủ ngữ. 'Failed' là dạng quá khứ/tính từ (như trong 'a failed attempt'), không thể tự đứng làm danh từ chủ ngữ ở đây." },
  { id: "n011", question: "Her _____ in the competition was outstanding. (achieve)", options: ["achieve", "achiever", "achieved", "achievement"], correctIndex: 3, explanation: "'Achievement' là danh từ trừu tượng của 'achieve' (hậu tố '-ment'), chỉ 'thành tích'. Đứng sau 'Her' làm chủ ngữ, câu cần danh từ chỉ sự việc chứ không phải người. 'Achiever' cũng là danh từ nhưng chỉ 'người đạt được thành tích', không hợp ngữ cảnh 'thành tích của cô ấy trong cuộc thi'." },
  { id: "n012", question: "He deserves official _____ for his work. (recognize)", options: ["recognize", "recognizable", "recognition", "recognized"], correctIndex: 2, explanation: "'Recognition' là danh từ của 'recognize', hình thành với hậu tố '-tion', nghĩa 'sự công nhận'. Đứng sau tính từ 'official' và làm tân ngữ của 'deserves', vị trí này cần danh từ. 'Recognizable' là tính từ (hậu tố '-able', nghĩa 'có thể nhận ra') nên không thể đứng sau tính từ khác ở vị trí danh từ." },
  { id: "n013", question: "Good _____ is key to a successful event. (organize)", options: ["organize", "organizational", "organized", "organization"], correctIndex: 3, explanation: "'Organization' (hậu tố '-ation' từ 'organize') là danh từ chỉ 'sự tổ chức/khâu tổ chức', đứng sau tính từ 'Good' làm chủ ngữ của câu. 'Organizational' là tính từ (như trong 'organizational skills'), không thể tự làm chủ ngữ đứng một mình." },
  { id: "n014", question: "The _____ of penicillin changed the world. (discover)", options: ["discover", "discovered", "discoverer", "discovery"], correctIndex: 3, explanation: "'Discovery' là danh từ của 'discover', đổi đuôi '-er' thành '-y' để chỉ 'sự khám phá' (khác với 'discoverer' chỉ người khám phá). Sau 'The', câu cần danh từ chỉ sự việc làm chủ ngữ vì chủ thể ở đây là sự kiện khám phá ra penicillin, không phải một người." },
  { id: "n015", question: "There is still room for _____ in your writing. (improve)", options: ["improve", "improving", "improved", "improvement"], correctIndex: 3, explanation: "'Improvement' là danh từ của 'improve' (hậu tố '-ment'), nghĩa 'sự cải thiện'. Đứng sau giới từ 'for' trong cụm cố định 'room for improvement', vị trí sau giới từ luôn cần danh từ hoặc V-ing. 'Improving' tuy có đuôi '-ing' nhưng ở đây là động danh từ ít tự nhiên hơn hẳn so với danh từ chuẩn 'improvement' vốn được dùng cố định trong cụm này." },
  { id: "n016", question: "The _____ of the crime took several months. (investigate)", options: ["investigate", "investigative", "investigator", "investigation"], correctIndex: 3, explanation: "'Investigation' là danh từ của 'investigate' (hậu tố '-tion'), chỉ 'cuộc điều tra'. Đứng sau 'The' làm chủ ngữ của câu, cần danh từ chỉ sự việc. 'Investigator' cũng là danh từ nhưng chỉ người (thanh tra/điều tra viên), không phù hợp vì chủ ngữ ở đây là bản thân cuộc điều tra, không phải con người." },
  { id: "n017", question: "The speaker gave a warm _____ to the audience. (introduce)", options: ["introduce", "introducer", "introduction", "introductory"], correctIndex: 2, explanation: "'Introduction' là danh từ của 'introduce' (đổi thành '-tion'), nghĩa 'lời giới thiệu'. Sau mạo từ 'a' và tính từ 'warm', chỗ trống cần danh từ làm tân ngữ của 'gave'. 'Introductory' là tính từ (hậu tố '-ory', nghĩa 'có tính giới thiệu, mở đầu') nên không thể đứng ở vị trí danh từ sau 'a warm'." },
  { id: "n018", question: "The _____ lasted for three hours. (negotiate)", options: ["negotiate", "negotiable", "negotiation", "negotiator"], correctIndex: 2, explanation: "'Negotiation' là danh từ của 'negotiate' (hậu tố '-tion'), chỉ 'cuộc đàm phán', đứng sau 'The' làm chủ ngữ của động từ 'lasted'. 'Negotiator' là danh từ chỉ người đàm phán nên không hợp nghĩa vì chủ thể 'kéo dài ba giờ' phải là sự việc, không phải một cá nhân." },
  { id: "n019", question: "Her _____ at the theater received a standing ovation. (perform)", options: ["perform", "performer", "performing", "performance"], correctIndex: 3, explanation: "'Performance' là danh từ của 'perform' (hậu tố '-ance'), nghĩa 'buổi biểu diễn'. Đứng sau sở hữu cách 'Her' làm chủ ngữ nhận 'a standing ovation', cần danh từ chỉ sự việc. 'Performer' cũng là danh từ nhưng chỉ người biểu diễn, không phải bản thân buổi diễn nên không khớp nghĩa câu." },
  { id: "n020", question: "The weather _____ turned out to be accurate. (predict)", options: ["predict", "predictable", "prediction", "predicted"], correctIndex: 2, explanation: "'Prediction' là danh từ của 'predict' (hậu tố '-tion'), ghép với 'weather' thành cụm 'weather prediction' (dự báo thời tiết) làm chủ ngữ câu. 'Predictable' là tính từ (hậu tố '-able', nghĩa 'có thể đoán trước') nên không thể ghép sau danh từ 'weather' để tạo chủ ngữ như vậy." },
  { id: "n021", question: "His _____ to the letter came three days later. (respond)", options: ["respond", "responsive", "responsibly", "response"], correctIndex: 3, explanation: "'Response' là danh từ của 'respond' (bỏ đuôi '-d', thêm '-se'), nghĩa 'sự hồi đáp'. Sau sở hữu cách 'His' làm chủ ngữ, câu cần danh từ. 'Responsive' là tính từ (nghĩa 'biết phản hồi nhanh nhạy') nên không thể đứng ở vị trí danh từ chủ ngữ này." },
  { id: "n022", question: "The _____ process was completely transparent. (select)", options: ["select", "selected", "selective", "selection"], correctIndex: 3, explanation: "'Selection' là danh từ của 'select' (hậu tố '-tion'), ở đây đóng vai trò danh từ bổ nghĩa cho danh từ 'process' tạo thành cụm 'selection process' (quy trình tuyển chọn). 'Selective' là tính từ (nghĩa 'có chọn lọc') mang nghĩa khác và không tạo thành cụm quen thuộc như 'selection process'." },
  { id: "n023", question: "The _____ of the document into Vietnamese took two days. (translate)", options: ["translate", "translator", "translatable", "translation"], correctIndex: 3, explanation: "'Translation' là danh từ của 'translate' (hậu tố '-tion'), nghĩa 'bản dịch/việc dịch thuật', đứng sau 'The' làm chủ ngữ. 'Translator' là danh từ chỉ người dịch, không phù hợp vì chủ ngữ cần là hành động dịch tài liệu, không phải con người." },
  { id: "n024", question: "A deep _____ of the topic is required. (understand)", options: ["understand", "understanding", "understood", "understandable"], correctIndex: 1, explanation: "'Understanding' ở đây là danh từ hóa từ động từ 'understand' bằng dạng V-ing, nghĩa 'sự am hiểu'. Sau mạo từ 'A' và tính từ 'deep', vị trí này cần danh từ làm chủ ngữ. 'Understandable' là tính từ (nghĩa 'có thể hiểu được') nên không thể đứng sau 'A deep' ở vai trò danh từ." },
  { id: "n025", question: "What is your _____? (prefer — food)", options: ["prefer", "preferred", "preferable", "preference"], correctIndex: 3, explanation: "'Preference' là danh từ của 'prefer' (hậu tố '-ence'), nghĩa 'sở thích/sự ưu tiên'. Đứng sau sở hữu cách 'your', câu hỏi cần một danh từ làm bổ ngữ. 'Preferable' là tính từ (nghĩa 'được ưa thích hơn') nên không thể đứng ngay sau 'your' ở vị trí danh từ." },
  { id: "n026", question: "The _____ of stamps is his main hobby. (collect)", options: ["collect", "collector", "collection", "collective"], correctIndex: 2, explanation: "'Collection' là danh từ của 'collect' (hậu tố '-tion'), nghĩa 'bộ sưu tập/việc sưu tầm', đứng sau 'The' làm chủ ngữ. 'Collector' là danh từ chỉ người sưu tầm, khác nghĩa với hành động/bộ sưu tập nên không khớp câu này." },
  { id: "n027", question: "Her flat _____ of the offer shocked everyone. (refuse)", options: ["refuse", "refusal", "refused", "refusable"], correctIndex: 1, explanation: "'Refusal' là danh từ của 'refuse' (hậu tố '-al'), nghĩa 'sự từ chối'. Sau sở hữu cách 'Her' và tính từ 'flat' (dứt khoát), cần một danh từ làm chủ ngữ. 'Refused' là dạng quá khứ/quá khứ phân từ của động từ, không thể đóng vai trò danh từ ở đây." },
  { id: "n028", question: "The _____ between the two events is obvious. (relate)", options: ["relate", "related", "relative", "relationship"], correctIndex: 3, explanation: "'Relationship' là danh từ của 'relate', hình thành với hậu tố '-ship', nghĩa 'mối liên hệ'. Đứng sau 'The' làm chủ ngữ và đi với giới từ 'between', câu cần danh từ. 'Related' là tính từ (nghĩa 'có liên quan') nên không thể tự làm chủ ngữ đứng một mình." },
  { id: "n029", question: "Job _____ for this position are very strict. (require)", options: ["require", "required", "requiring", "requirements"], correctIndex: 3, explanation: "'Requirements' là danh từ số nhiều của 'require' (hậu tố '-ment' cộng 's'), nghĩa 'yêu cầu/điều kiện'. Động từ 'are' ở số nhiều cho biết chủ ngữ phải là danh từ số nhiều, ghép sau 'Job' thành 'job requirements'. 'Required' là tính từ/phân từ (nghĩa 'được yêu cầu') nên không thể tự làm chủ ngữ số nhiều ở đây." },
  { id: "n030", question: "There was great _____ among the group members. (cooperate)", options: ["cooperate", "cooperative", "cooperating", "cooperation"], correctIndex: 3, explanation: "'Cooperation' là danh từ của 'cooperate' (hậu tố '-tion'), nghĩa 'sự hợp tác', đứng sau tính từ 'great' làm chủ ngữ thực trong cấu trúc 'there was'. 'Cooperative' là tính từ (nghĩa 'có tinh thần hợp tác') nên không thể đứng sau 'great' để làm danh từ chủ ngữ được." },
  { id: "n031", question: "He has great _____ in painting. (skilled)", options: ["skill", "skillful", "skillfully", "skilling"], correctIndex: 0, explanation: "'Skill' là danh từ cơ bản (không cần hậu tố), nghĩa 'kỹ năng', đứng sau tính từ 'great' làm tân ngữ của 'has'. 'Skillful' là tính từ (hậu tố '-ful') và 'skillfully' là trạng từ (hậu tố '-ly'), cả hai đều không thể đứng ở vị trí danh từ ngay sau 'great'." },
  { id: "n032", question: "The government announced a new _____ to fight poverty. (initiate)", options: ["initiate", "initiative", "initial", "initially"], correctIndex: 1, explanation: "'Initiative' ở đây là danh từ (từ gốc 'initiate' thêm '-ive'), nghĩa 'sáng kiến/chương trình hành động'. Sau mạo từ 'a' và tính từ 'new', câu cần một danh từ làm tân ngữ của 'announced'. 'Initial' là tính từ (nghĩa 'ban đầu') và 'initially' là trạng từ, đều không phù hợp vị trí danh từ này." },
  { id: "n033", question: "She showed great _____ in difficult situations. (patient)", options: ["patient", "patiently", "patience", "patientness"], correctIndex: 2, explanation: "'Patience' là danh từ trừu tượng của tính từ 'patient' (hậu tố '-ence'), nghĩa 'sự kiên nhẫn'. Đứng sau 'great' làm tân ngữ của 'showed', cần một danh từ. 'Patiently' là trạng từ (hậu tố '-ly') nên không thể đứng sau tính từ 'great' ở vị trí danh từ." },
  { id: "n034", question: "Her _____ to the company has been invaluable. (contribute)", options: ["contribute", "contributive", "contributor", "contribution"], correctIndex: 3, explanation: "'Contribution' là danh từ của 'contribute' (hậu tố '-tion'), nghĩa 'sự đóng góp', đứng sau 'Her' làm chủ ngữ. 'Contributor' là danh từ chỉ người đóng góp (con người), khác với 'sự đóng góp' là hành động/giá trị nên không khớp nghĩa câu này." },
  { id: "n035", question: "The _____ of the new product caused much excitement. (announce)", options: ["announce", "announcer", "announced", "announcement"], correctIndex: 3, explanation: "'Announcement' là danh từ của 'announce' (hậu tố '-ment'), nghĩa 'thông báo', đứng sau 'The' làm chủ ngữ. 'Announcer' là danh từ chỉ người thông báo/phát thanh viên, không phải bản thân sự việc thông báo nên không phù hợp ở đây." },
  { id: "n036", question: "There was much _____ about the new policy. (argue)", options: ["argue", "arguable", "arguably", "argument"], correctIndex: 3, explanation: "'Argument' là danh từ của 'argue' (hậu tố '-ment'), nghĩa 'cuộc tranh luận'. Sau lượng từ 'much' (dùng cho danh từ không đếm được), câu cần danh từ. 'Arguable' là tính từ (nghĩa 'có thể tranh cãi') và 'arguably' là trạng từ, cả hai không thể đứng sau 'much' ở vị trí danh từ." },
  { id: "n037", question: "He acted with great _____. (determine)", options: ["determine", "determined", "determining", "determination"], correctIndex: 3, explanation: "'Determination' là danh từ trừu tượng của 'determine' (hậu tố '-ation'), nghĩa 'sự quyết tâm'. Sau giới từ 'with' và tính từ 'great', vị trí này cần danh từ. 'Determined' là tính từ/phân từ (nghĩa 'quyết tâm, kiên định') nên không thể đứng ở vị trí danh từ sau 'great'." },
  { id: "n038", question: "She found _____ in music when she was sad. (console)", options: ["console", "consolable", "consolation", "consoling"], correctIndex: 2, explanation: "'Consolation' là danh từ của 'console' (hậu tố '-tion'), nghĩa 'sự an ủi', làm tân ngữ của động từ 'found'. Vị trí sau động từ 'found' cần một danh từ cụ thể. 'Consoling' là tính từ/phân từ (nghĩa 'mang tính an ủi') nên không đóng vai trò danh từ được tìm thấy ở đây." },
  { id: "n039", question: "The _____ of the two companies took months. (merge)", options: ["merge", "merged", "merging", "merger"], correctIndex: 3, explanation: "'Merger' là danh từ của 'merge', thêm '-er' để chỉ 'sự sáp nhập (công ty)' - khác với nghĩa người thông thường của '-er'. Đứng sau 'The' làm chủ ngữ, câu cần danh từ. 'Merging' (V-ing) cũng có thể làm danh động từ nhưng 'merger' là danh từ chuẩn và tự nhiên hơn trong ngữ cảnh kinh doanh này." },
  { id: "n040", question: "She has a natural _____ for languages. (able)", options: ["able", "ability", "ably", "enabled"], correctIndex: 1, explanation: "'Ability' là danh từ của tính từ 'able' (hậu tố '-ity'), nghĩa 'khả năng'. Sau mạo từ 'a' và tính từ 'natural', chỗ trống cần danh từ làm tân ngữ của 'has'. 'Ably' là trạng từ (hậu tố '-ly', nghĩa 'một cách tài tình') nên không thể đứng ở vị trí danh từ này." },
  { id: "n041", question: "His _____ surprised everyone in the room. (generous)", options: ["generous", "generously", "generosity", "generousness"], correctIndex: 2, explanation: "'Generosity' là danh từ trừu tượng của tính từ 'generous' (hậu tố '-ity'), nghĩa 'sự hào phóng'. Đứng sau sở hữu cách 'His' làm chủ ngữ, câu cần danh từ. 'Generously' là trạng từ (hậu tố '-ly') nên không thể làm chủ ngữ đứng sau 'His'." },
  { id: "n042", question: "The _____ of the old building will take three months. (demolish)", options: ["demolish", "demolisher", "demolished", "demolition"], correctIndex: 3, explanation: "'Demolition' là danh từ của 'demolish' (đổi thành hậu tố '-tion'), nghĩa 'việc phá dỡ', đứng sau 'The' làm chủ ngữ. 'Demolisher' ít dùng và mang nghĩa người/thiết bị phá dỡ, không hợp nghĩa 'quá trình kéo dài ba tháng' như câu yêu cầu." },
  { id: "n043", question: "She won a _____ for her academic achievements. (scholar)", options: ["scholar", "scholarly", "scholastic", "scholarship"], correctIndex: 3, explanation: "'Scholarship' là danh từ ghép từ 'scholar' bằng hậu tố '-ship', nghĩa 'học bổng'. Sau mạo từ 'a', câu cần danh từ làm tân ngữ của 'won'. 'Scholarly' là tính từ (nghĩa 'mang tính học thuật') nên không thể đứng sau 'a' ở vị trí danh từ được." },
  { id: "n044", question: "The _____ of the meeting was rescheduled. (cancel)", options: ["cancel", "cancelled", "cancellation", "cancelling"], correctIndex: 2, explanation: "'Cancellation' là danh từ của 'cancel' (hậu tố '-ation'), nghĩa 'sự hủy bỏ', đứng sau 'The' làm chủ ngữ. 'Cancelled' là dạng quá khứ/phân từ của động từ nên không thể tự làm danh từ chủ ngữ trong câu này." },
  { id: "n045", question: "His _____ came as a complete surprise to us. (resign)", options: ["resign", "resigned", "resigning", "resignation"], correctIndex: 3, explanation: "'Resignation' là danh từ của 'resign' (hậu tố '-ation'), nghĩa 'đơn từ chức', đứng sau 'His' làm chủ ngữ. 'Resigned' là tính từ/phân từ (nghĩa 'cam chịu, đã từ chức') nên không thể tự đóng vai trò danh từ chủ ngữ." },
  { id: "n046", question: "She took full _____ for the mistake. (responsible)", options: ["responsible", "responsibly", "responsiveness", "responsibility"], correctIndex: 3, explanation: "'Responsibility' là danh từ của tính từ 'responsible' (hậu tố '-ity'), nghĩa 'trách nhiệm', dùng trong cụm cố định 'take responsibility for'. Sau tính từ 'full', vị trí này cần danh từ. 'Responsiveness' nghĩa khác hẳn ('khả năng phản hồi nhanh nhạy') nên dù cùng là danh từ vẫn không hợp nghĩa câu." },
  { id: "n047", question: "The company has a strict _____ against discrimination. (politic)", options: ["politic", "political", "politically", "policy"], correctIndex: 3, explanation: "'Policy' là danh từ chỉ 'chính sách', đứng sau mạo từ 'a' và tính từ 'strict' làm tân ngữ của 'has'. 'Political' là tính từ (hậu tố '-al', nghĩa 'thuộc về chính trị') nên không thể đứng ở vị trí danh từ ngay sau 'a strict'." },
  { id: "n048", question: "He showed great _____ in learning a new skill. (persistent)", options: ["persistent", "persistently", "persistence", "persistency"], correctIndex: 2, explanation: "'Persistence' là danh từ trừu tượng của tính từ 'persistent' (hậu tố '-ence'), nghĩa 'sự kiên trì'. Sau tính từ 'great', câu cần danh từ làm tân ngữ của 'showed'. 'Persistently' là trạng từ (hậu tố '-ly') nên không thể đứng ở vị trí danh từ này." },
  { id: "n049", question: "The _____ of living in the city has increased. (expensive)", options: ["expensive", "expensively", "expense", "cost"], correctIndex: 3, explanation: "Đây là cụm cố định 'the cost of living' (chi phí sinh hoạt), nên đáp án là danh từ 'cost' chứ không phải suy luận trực tiếp từ 'expensive'. Sau 'The' và trước 'of living', vị trí này luôn cần danh từ 'cost'. 'Expensive' là tính từ (nghĩa 'đắt đỏ') nên không thể thay thế trong cụm cố định này, dù nghĩa có liên quan." },
  { id: "n050", question: "The company's _____ plan was approved by investors. (expand)", options: ["expand", "expanded", "expander", "expansion"], correctIndex: 3, explanation: "'Expansion' là danh từ của 'expand' (hậu tố '-sion'), ở đây đứng trước danh từ 'plan' để tạo cụm 'expansion plan' (kế hoạch mở rộng). 'Expanded' là tính từ/phân từ (nghĩa 'đã được mở rộng') mang nghĩa khác, không tạo thành cụm quen thuộc như đáp án đúng." },
  { id: "n051", question: "The _____ of the new law sparked controversy. (implement)", options: ["implement", "implemental", "implementation", "implementing"], correctIndex: 2, explanation: "'Implementation' là danh từ của 'implement' (hậu tố '-ation'), nghĩa 'việc thực thi/áp dụng', đứng sau 'The' làm chủ ngữ. 'Implementing' (V-ing) tuy có thể làm danh động từ nhưng không tự nhiên bằng danh từ chuẩn 'implementation' trong văn phong này." },
  { id: "n052", question: "She described her _____ at the art exhibition. (observe)", options: ["observe", "observed", "observer", "observation"], correctIndex: 3, explanation: "'Observation' là danh từ của 'observe' (hậu tố '-ation'), nghĩa 'sự quan sát/nhận xét', đứng sau 'her' làm tân ngữ của 'described'. 'Observer' là danh từ chỉ người quan sát (con người), không phải bản thân nhận xét nên không khớp nghĩa câu." },
  { id: "n053", question: "The _____ of the patient's recovery was faster than expected. (proceed)", options: ["proceed", "proceedable", "procedure", "proceeding"], correctIndex: 3, explanation: "'Procedure' là danh từ liên quan đến 'proceed', chỉ 'quá trình/diễn tiến' (trong y khoa hay dùng để nói tiến trình hồi phục). Đứng sau 'The' làm chủ ngữ, câu cần danh từ. 'Proceeding' cũng là danh từ nhưng thường chỉ 'thủ tục pháp lý' hoặc 'buổi họp', kém tự nhiên hơn trong ngữ cảnh nói về quá trình hồi phục của bệnh nhân." },
  { id: "n054", question: "We need official _____ before starting the project. (authorize)", options: ["authorize", "authorized", "authorization", "authoritative"], correctIndex: 2, explanation: "'Authorization' là danh từ của 'authorize' (hậu tố '-ation'), nghĩa 'sự cho phép/ủy quyền'. Sau tính từ 'official', câu cần danh từ làm tân ngữ của 'need'. 'Authoritative' là tính từ (nghĩa 'có thẩm quyền, đáng tin') nên không thể đứng ở vị trí danh từ này." },
  { id: "n055", question: "The report gave a detailed _____ of the incident. (describe)", options: ["describe", "described", "descriptive", "description"], correctIndex: 3, explanation: "'Description' là danh từ của 'describe' (hậu tố '-tion'), nghĩa 'bản mô tả'. Sau mạo từ 'a' và tính từ 'detailed', câu cần danh từ làm tân ngữ của 'gave'. 'Descriptive' là tính từ (hậu tố '-ive', nghĩa 'mang tính mô tả') nên không thể đứng ở vị trí danh từ sau 'a detailed'." },
  { id: "n056", question: "She applied for a _____ at the local hospital. (vacant)", options: ["vacant", "vacancy", "vacate", "vacantly"], correctIndex: 1, explanation: "'Vacancy' là danh từ của tính từ 'vacant' (hậu tố '-ancy'), nghĩa 'vị trí còn trống/việc làm trống'. Sau mạo từ 'a', câu cần danh từ làm tân ngữ của giới từ 'for'. 'Vacate' là động từ (nghĩa 'rời khỏi, bỏ trống') nên không thể đứng sau 'a' ở vị trí danh từ." },
  { id: "n057", question: "The new _____ will replace the old one next month. (regulate)", options: ["regulate", "regulated", "regulator", "regulation"], correctIndex: 3, explanation: "'Regulation' là danh từ của 'regulate' (hậu tố '-tion'), nghĩa 'quy định', đứng sau tính từ 'new' làm chủ ngữ. 'Regulator' là danh từ chỉ người/cơ quan quản lý (chủ thể ban hành), khác với 'quy định' là văn bản/nội dung nên không khớp nghĩa 'sẽ thay thế cái cũ vào tháng sau'." },
  { id: "n058", question: "Her _____ to details makes her an excellent editor. (attend)", options: ["attend", "attendance", "attention", "attending"], correctIndex: 2, explanation: "'Attention' là danh từ của 'attend' mang nghĩa 'sự chú ý' (khác với 'attendance' nghĩa là 'sự có mặt/điểm danh'). Sau 'Her' làm chủ ngữ và trong cụm cố định 'attention to detail', câu cần đúng danh từ này. 'Attendance' tuy cùng là danh từ phái sinh từ 'attend' nhưng sai nghĩa hoàn toàn trong ngữ cảnh 'chú ý đến chi tiết'." },
  { id: "n059", question: "The board accepted his _____ for the new product line. (propose)", options: ["propose", "proposing", "proposal", "proposer"], correctIndex: 2, explanation: "'Proposal' là danh từ của 'propose' (hậu tố '-al'), nghĩa 'đề xuất/bản đề nghị'. Sau sở hữu cách 'his', câu cần danh từ làm tân ngữ của 'accepted'. 'Proposer' là danh từ chỉ người đề xuất (con người), không phải bản thân đề xuất nên không khớp nghĩa câu." },
  { id: "n060", question: "She received wide _____ for her humanitarian work. (acclaim)", options: ["acclaim", "acclaiming", "acclaimable", "acclamation"], correctIndex: 3, explanation: "'Acclamation' là danh từ của 'acclaim' (hậu tố '-ation'), nghĩa 'sự hoan nghênh, tán dương rộng rãi'. Sau tính từ 'wide', câu cần danh từ làm tân ngữ của 'received'. 'Acclaiming' (V-ing) ít tự nhiên hơn hẳn so với danh từ chuẩn 'acclamation' trong văn phong trang trọng này." },
  { id: "n061", question: "The _____ of funds from the project was questioned. (divert)", options: ["divert", "diverting", "divertive", "diversion"], correctIndex: 3, explanation: "'Diversion' là danh từ của 'divert' (hậu tố '-sion'), nghĩa 'sự chuyển hướng/rút chuyển (quỹ)'. Đứng sau 'The' làm chủ ngữ, câu cần danh từ. 'Diverting' (V-ing) mang nghĩa khác ('gây xao lãng, thú vị') khi dùng làm tính từ, không phù hợp ngữ cảnh nói về việc rút quỹ." },
  { id: "n062", question: "She sought medical _____ after the accident. (assist)", options: ["assist", "assistive", "assistant", "assistance"], correctIndex: 3, explanation: "'Assistance' là danh từ của 'assist' (hậu tố '-ance'), nghĩa 'sự trợ giúp'. Sau tính từ 'medical', câu cần danh từ làm tân ngữ của 'sought'. 'Assistant' là danh từ chỉ người trợ lý (con người), không phải hành động giúp đỡ nên không khớp nghĩa 'tìm kiếm sự trợ giúp y tế'." },
  { id: "n063", question: "The _____ of the contract is still being discussed. (extend)", options: ["extend", "extended", "extender", "extension"], correctIndex: 3, explanation: "'Extension' là danh từ của 'extend' (hậu tố '-sion'), nghĩa 'việc gia hạn', đứng sau 'The' làm chủ ngữ. 'Extended' là tính từ/phân từ (nghĩa 'đã được kéo dài') nên không thể tự làm chủ ngữ đứng một mình ở đây." },
  { id: "n064", question: "There was no clear _____ to the problem. (solve)", options: ["solve", "solvable", "solver", "solution"], correctIndex: 3, explanation: "'Solution' là danh từ của 'solve' (hậu tố '-tion'), nghĩa 'giải pháp', dùng trong cụm cố định 'solution to a problem'. Sau tính từ 'clear', câu cần danh từ. 'Solvable' là tính từ (nghĩa 'có thể giải được') nên không thể đứng sau 'clear' ở vị trí danh từ này." },
  { id: "n065", question: "The _____ of a new director was announced yesterday. (appoint)", options: ["appoint", "appointee", "appointment", "appointing"], correctIndex: 2, explanation: "'Appointment' là danh từ của 'appoint' (hậu tố '-ment'), nghĩa 'sự bổ nhiệm', đứng sau 'The' làm chủ ngữ. 'Appointee' là danh từ chỉ người được bổ nhiệm (con người), khác với bản thân hành động bổ nhiệm nên không khớp nghĩa câu." },
  { id: "n066", question: "They reached an _____ after three days of talks. (agree)", options: ["agree", "agreeable", "agreed", "agreement"], correctIndex: 3, explanation: "'Agreement' là danh từ của 'agree' (hậu tố '-ment'), nghĩa 'thỏa thuận', dùng trong cụm cố định 'reach an agreement'. Sau mạo từ 'an', câu cần danh từ làm tân ngữ của 'reached'. 'Agreeable' là tính từ (nghĩa 'dễ chịu, đồng ý được') nên không thể đứng sau 'an' ở vị trí danh từ." },
  { id: "n067", question: "Her _____ with the new system was immediate. (familiar)", options: ["familiar", "familiarize", "familiarly", "familiarity"], correctIndex: 3, explanation: "'Familiarity' là danh từ trừu tượng của tính từ 'familiar' (hậu tố '-ity'), nghĩa 'sự quen thuộc'. Sau 'Her' làm chủ ngữ, câu cần danh từ. 'Familiarize' là động từ (nghĩa 'làm quen với') nên không thể đứng sau sở hữu cách 'Her' ở vị trí danh từ chủ ngữ." },
  { id: "n068", question: "The _____ of the building was completed ahead of schedule. (construct)", options: ["construct", "constructive", "constructor", "construction"], correctIndex: 3, explanation: "'Construction' là danh từ của 'construct' (hậu tố '-tion'), nghĩa 'việc xây dựng', đứng sau 'The' làm chủ ngữ. 'Constructive' là tính từ (nghĩa 'mang tính xây dựng, tích cực' - dùng cho ý kiến, đóng góp) nên không phù hợp nghĩa 'công trình được hoàn thành' ở đây." },
  { id: "n069", question: "She showed considerable _____ in managing the crisis. (competent)", options: ["competent", "competently", "competency", "compete"], correctIndex: 2, explanation: "'Competency' (hay 'competence') là danh từ của tính từ 'competent' (hậu tố '-ency'), nghĩa 'năng lực'. Sau tính từ 'considerable', câu cần danh từ làm tân ngữ của 'showed'. 'Competently' là trạng từ (hậu tố '-ly') nên không thể đứng sau 'considerable' ở vị trí danh từ." },
  { id: "n070", question: "The _____ in the market has intensified recently. (compete)", options: ["compete", "competitor", "competitive", "competition"], correctIndex: 3, explanation: "'Competition' là danh từ của 'compete' (hậu tố '-tion'), nghĩa 'sự cạnh tranh', đứng sau 'The' làm chủ ngữ. 'Competitor' là danh từ chỉ đối thủ cạnh tranh (con người/tổ chức), không phải bản thân hiện tượng cạnh tranh nên không khớp nghĩa câu." },
  { id: "n071", question: "She expressed her _____ at the committee's decision. (disappoint)", options: ["disappoint", "disappointing", "disappointed", "disappointment"], correctIndex: 3, explanation: "'Disappointment' là danh từ của 'disappoint' (hậu tố '-ment'), nghĩa 'sự thất vọng', đứng sau 'her' làm tân ngữ của 'expressed'. 'Disappointed' là tính từ (nghĩa 'cảm thấy thất vọng', mô tả người) nên không thể đứng sau sở hữu cách 'her' ở vị trí danh từ." },
  { id: "n072", question: "The _____ between theory and practice is often challenging. (connect)", options: ["connect", "connected", "connection", "connective"], correctIndex: 2, explanation: "'Connection' là danh từ của 'connect' (hậu tố '-tion'), nghĩa 'mối liên hệ', dùng trong cụm 'connection between X and Y'. Sau 'The' làm chủ ngữ, câu cần danh từ. 'Connected' là tính từ/phân từ (nghĩa 'được kết nối') nên không thể tự làm chủ ngữ đứng một mình." },
  { id: "n073", question: "He made a significant _____ to medical research. (discover)", options: ["discover", "discovery", "discoverable", "discovered"], correctIndex: 1, explanation: "'Discovery' là danh từ của 'discover' (đổi '-er' thành '-y'), nghĩa 'phát hiện', dùng trong cụm 'make a discovery'. Sau tính từ 'significant', câu cần danh từ làm tân ngữ của 'made'. 'Discoverable' là tính từ (nghĩa 'có thể khám phá ra') nên không thể đứng ở vị trí danh từ này." },
  { id: "n074", question: "The company faces stiff _____ from overseas rivals. (compete)", options: ["compete", "competitive", "competitor", "competition"], correctIndex: 3, explanation: "'Competition' là danh từ của 'compete' (hậu tố '-tion'), đứng sau tính từ 'stiff' làm tân ngữ của 'faces'. 'Competitive' là tính từ (nghĩa 'có tính cạnh tranh') và 'competitor' là danh từ chỉ người/đối thủ, cả hai đều không hợp vì câu cần danh từ chỉ hiện tượng cạnh tranh nói chung." },
  { id: "n075", question: "Her _____ with the new colleagues was warm and friendly. (interact)", options: ["interact", "interactive", "interaction", "interacting"], correctIndex: 2, explanation: "'Interaction' là danh từ của 'interact' (hậu tố '-tion'), nghĩa 'sự tương tác', đứng sau 'Her' làm chủ ngữ. 'Interactive' là tính từ (nghĩa 'có tính tương tác', dùng cho công nghệ, trò chơi) nên không thể tự làm chủ ngữ ở vị trí này." },
  { id: "n076", question: "The _____ of the bridge will take two years. (construct)", options: ["construct", "constructing", "constructive", "construction"], correctIndex: 3, explanation: "'Construction' là danh từ của 'construct' (hậu tố '-tion'), nghĩa 'việc xây dựng', đứng sau 'The' làm chủ ngữ. 'Constructive' là tính từ mang nghĩa khác hẳn ('mang tính xây dựng, tích cực' - dùng cho lời góp ý), không liên quan đến việc thi công cây cầu này." },
  { id: "n077", question: "She expressed deep _____ for those who lost their jobs. (sympathize)", options: ["sympathize", "sympathetic", "sympathetically", "sympathy"], correctIndex: 3, explanation: "'Sympathy' là danh từ của 'sympathize' (đổi thành '-y'), nghĩa 'sự thông cảm', dùng trong cụm 'express sympathy for'. Sau tính từ 'deep', câu cần danh từ làm tân ngữ của 'expressed'. 'Sympathetic' là tính từ (hậu tố '-etic') nên không thể đứng sau 'deep' ở vị trí danh từ." },
  { id: "n078", question: "The _____ of power is a fundamental principle of democracy. (separate)", options: ["separate", "separately", "separation", "separated"], correctIndex: 2, explanation: "'Separation' là danh từ của 'separate' (hậu tố '-ation'), nghĩa 'sự phân chia', dùng trong cụm chính trị 'separation of powers'. Sau 'The' làm chủ ngữ, câu cần danh từ. 'Separately' là trạng từ (hậu tố '-ly', nghĩa 'một cách riêng rẽ') nên không thể làm chủ ngữ đứng sau 'The'." },
  { id: "n079", question: "He made an important _____ at the board meeting. (contribute)", options: ["contribute", "contributing", "contributor", "contribution"], correctIndex: 3, explanation: "'Contribution' là danh từ của 'contribute' (hậu tố '-tion'), dùng trong cụm 'make a contribution'. Sau tính từ 'important', câu cần danh từ làm tân ngữ của 'made'. 'Contributor' là danh từ chỉ người đóng góp (con người), không khớp với cấu trúc 'make a + danh từ chỉ hành động' ở đây." },
  { id: "n080", question: "She has a strong _____ toward justice. (commit)", options: ["commit", "committed", "committer", "commitment"], correctIndex: 3, explanation: "'Commitment' là danh từ của 'commit' (hậu tố '-ment'), nghĩa 'sự cam kết/tận tâm'. Sau tính từ 'strong', câu cần danh từ làm tân ngữ của 'has'. 'Committed' là tính từ/phân từ (nghĩa 'tận tâm, cam kết') nên không thể đứng sau tính từ khác ở vị trí danh từ." },
  { id: "n081", question: "The _____ of the problem took hours to identify. (cause)", options: ["cause", "causal", "causation", "causality"], correctIndex: 2, explanation: "'Causation' là danh từ trừu tượng chỉ 'mối quan hệ nhân quả/nguyên nhân', phái sinh liên quan đến 'cause' bằng hậu tố '-ation'. Đứng sau 'The' làm chủ ngữ, câu cần danh từ. 'Causal' là tính từ (nghĩa 'thuộc về nguyên nhân', như trong 'causal relationship') nên không thể tự làm chủ ngữ ở đây." },
  { id: "n082", question: "There was no _____ that the contract had been signed. (confirm)", options: ["confirm", "confirmed", "confirmable", "confirmation"], correctIndex: 3, explanation: "'Confirmation' là danh từ của 'confirm' (hậu tố '-ation'), nghĩa 'sự xác nhận', đứng sau 'no' làm chủ ngữ thực trong cấu trúc 'there was'. 'Confirmed' là tính từ/phân từ (nghĩa 'đã được xác nhận') nên không thể tự làm danh từ chủ ngữ ở đây." },
  { id: "n083", question: "The _____ of the experiment surprised the scientists. (conclude)", options: ["conclude", "concluded", "conclusive", "conclusion"], correctIndex: 3, explanation: "'Conclusion' là danh từ của 'conclude' (hậu tố '-sion'), nghĩa 'kết luận', đứng sau 'The' làm chủ ngữ. 'Conclusive' là tính từ (nghĩa 'có tính thuyết phục, dứt khoát') nên không thể đứng ở vị trí danh từ chủ ngữ này." },
  { id: "n084", question: "She earned a _____ for academic excellence. (scholar)", options: ["scholar", "scholarly", "scholarship", "scholastic"], correctIndex: 2, explanation: "'Scholarship' là danh từ ghép từ 'scholar' (hậu tố '-ship'), nghĩa 'học bổng'. Sau mạo từ 'a', câu cần danh từ làm tân ngữ của 'earned'. 'Scholastic' là tính từ (nghĩa 'thuộc về học thuật, trường học') nên không thể đứng sau 'a' ở vị trí danh từ." },
  { id: "n085", question: "The _____ of his findings was published in a journal. (summarize)", options: ["summarize", "summarized", "summarizer", "summary"], correctIndex: 3, explanation: "'Summary' là danh từ của 'summarize' (bỏ '-ize', thêm '-y'), nghĩa 'bản tóm tắt', đứng sau 'The' làm chủ ngữ. 'Summarizer' ít dùng và mang nghĩa người/công cụ tóm tắt, không tự nhiên bằng danh từ chuẩn 'summary' để nói về thứ 'được đăng trên tạp chí'." },
  { id: "n086", question: "She worked without pay as a _____ at the hospital. (volunteer)", options: ["volunteer", "voluntary", "voluntarily", "volunteering"], correctIndex: 0, explanation: "'Volunteer' là danh từ chỉ 'người tình nguyện', đứng sau mạo từ 'a' trong cụm 'as a volunteer'. 'Voluntary' là tính từ (nghĩa 'mang tính tự nguyện', như trong 'voluntary work') nên không thể đứng sau 'a' ở vị trí danh từ chỉ người này." },
  { id: "n087", question: "There was great _____ from the local community. (oppose)", options: ["oppose", "opposed", "opposer", "opposition"], correctIndex: 3, explanation: "'Opposition' là danh từ của 'oppose' (hậu tố '-tion'), nghĩa 'sự phản đối', đứng sau tính từ 'great' làm chủ ngữ thực trong cấu trúc 'there was'. 'Opposer' ít dùng, chỉ người phản đối, trong khi câu cần danh từ chỉ hiện tượng/mức độ phản đối chung từ cộng đồng." },
  { id: "n088", question: "The _____ of the proposal took place at the annual meeting. (present)", options: ["present", "presenter", "presented", "presentation"], correctIndex: 3, explanation: "'Presentation' là danh từ của 'present' (hậu tố '-ation'), nghĩa 'buổi thuyết trình', đứng sau 'The' làm chủ ngữ. 'Presenter' là danh từ chỉ người thuyết trình (con người), không phải bản thân sự kiện diễn ra tại cuộc họp nên không khớp nghĩa." },
  { id: "n089", question: "She gained international _____ for her research. (recognize)", options: ["recognize", "recognized", "recognizable", "recognition"], correctIndex: 3, explanation: "'Recognition' là danh từ của 'recognize' (hậu tố '-tion'), dùng trong cụm 'gain recognition'. Sau tính từ 'international', câu cần danh từ làm tân ngữ của 'gained'. 'Recognizable' là tính từ (nghĩa 'có thể nhận ra được') nên không thể đứng ở vị trí danh từ này." },
  { id: "n090", question: "They signed a formal _____ for peace. (declare)", options: ["declare", "declared", "declarative", "declaration"], correctIndex: 3, explanation: "'Declaration' là danh từ của 'declare' (hậu tố '-ation'), dùng trong cụm 'sign a declaration'. Sau tính từ 'formal', câu cần danh từ làm tân ngữ của 'signed'. 'Declarative' là tính từ (nghĩa 'mang tính tuyên bố', thường dùng trong ngữ pháp câu trần thuật) nên không hợp vị trí danh từ này." },
  { id: "n091", question: "The _____ between the two countries improved after the summit. (relate)", options: ["relate", "related", "relatable", "relations"], correctIndex: 3, explanation: "'Relations' (số nhiều) là danh từ của 'relate', chỉ 'quan hệ (ngoại giao/quốc tế)' - khi nói về quan hệ giữa hai quốc gia luôn dùng dạng số nhiều này. Đứng sau 'The' làm chủ ngữ, câu cần danh từ. 'Related' là tính từ (nghĩa 'có liên quan') nên không thể tự làm chủ ngữ được." },
  { id: "n092", question: "He has a _____ for getting into trouble. (tend)", options: ["tend", "tenderly", "tender", "tendency"], correctIndex: 3, explanation: "'Tendency' là danh từ của 'tend' (hậu tố '-ency'), nghĩa 'xu hướng', dùng trong cụm 'a tendency for/to'. Sau mạo từ 'a', câu cần danh từ làm tân ngữ của 'has'. 'Tender' ở đây dễ gây nhầm vì là tính từ (nghĩa 'mềm mại, dịu dàng'), hoàn toàn khác nghĩa và không phù hợp ngữ cảnh." },
  { id: "n093", question: "The _____ of her speech was very clear. (intend)", options: ["intend", "intended", "intending", "intention"], correctIndex: 3, explanation: "'Intention' là danh từ của 'intend' (hậu tố '-tion'), nghĩa 'dụng ý/mục đích', đứng sau 'The' làm chủ ngữ. 'Intended' là tính từ/phân từ (nghĩa 'được dự định') nên không thể tự làm chủ ngữ đứng một mình trong câu này." },
  { id: "n094", question: "She showed natural _____ as a leader from a young age. (lead)", options: ["lead", "leader", "leadership", "leading"], correctIndex: 2, explanation: "'Leadership' là danh từ của 'lead' (hậu tố '-ship'), nghĩa 'khả năng/tố chất lãnh đạo'. Sau tính từ 'natural', câu cần danh từ làm tân ngữ của 'showed'. 'Leader' là danh từ chỉ người lãnh đạo (con người cụ thể), khác với 'tố chất lãnh đạo' là phẩm chất trừu tượng nên không khớp nghĩa." },
  { id: "n095", question: "The _____ of the meeting was distributed to all staff. (minute)", options: ["minute", "minutes", "minutely", "minuter"], correctIndex: 1, explanation: "'Minutes' (luôn ở dạng số nhiều) là danh từ đặc biệt nghĩa 'biên bản cuộc họp', khác hẳn nghĩa 'phút' của 'minute' số ít. Đứng sau 'The' làm chủ ngữ, câu cần danh từ số nhiều này để khớp nghĩa. 'Minutely' là trạng từ (nghĩa 'một cách tỉ mỉ') nên hoàn toàn không phù hợp ở vị trí danh từ." },
  { id: "n096", question: "Her _____ to overcome challenges inspired the team. (determine)", options: ["determine", "determined", "determiner", "determination"], correctIndex: 3, explanation: "'Determination' là danh từ trừu tượng của 'determine' (hậu tố '-ation'), nghĩa 'sự quyết tâm', đứng sau 'Her' làm chủ ngữ. 'Determined' là tính từ (nghĩa 'quyết tâm, kiên định', mô tả người) nên không thể đứng sau sở hữu cách ở vị trí danh từ chủ ngữ này." },
  { id: "n097", question: "The _____ of the new office will begin next month. (renovate)", options: ["renovate", "renovating", "renovator", "renovation"], correctIndex: 3, explanation: "'Renovation' là danh từ của 'renovate' (hậu tố '-tion'), nghĩa 'việc cải tạo/tân trang', đứng sau 'The' làm chủ ngữ. 'Renovator' là danh từ chỉ người/đơn vị thi công cải tạo, không phải bản thân công việc sẽ 'bắt đầu vào tháng sau' nên không khớp nghĩa." },
  { id: "n098", question: "The _____ in oil prices affected the whole economy. (fluctuate)", options: ["fluctuate", "fluctuating", "fluctuator", "fluctuation"], correctIndex: 3, explanation: "'Fluctuation' là danh từ của 'fluctuate' (hậu tố '-ation'), nghĩa 'sự biến động', dùng trong cụm 'fluctuation in prices'. Sau 'The' làm chủ ngữ, câu cần danh từ. 'Fluctuating' là tính từ/phân từ (nghĩa 'đang biến động', mô tả trạng thái) nên không thể tự làm chủ ngữ đứng một mình." },
  { id: "n099", question: "She signed the _____ before starting work. (agree)", options: ["agree", "agreed", "agreeable", "agreement"], correctIndex: 3, explanation: "'Agreement' là danh từ của 'agree' (hậu tố '-ment'), dùng trong cụm 'sign an agreement'. Sau mạo từ 'the', câu cần danh từ làm tân ngữ của 'signed'. 'Agreeable' là tính từ (nghĩa 'dễ chịu, đồng ý được') nên không thể đứng sau 'the' ở vị trí danh từ." },
  { id: "n100", question: "He has a _____ in engineering from Oxford University. (qualify)", options: ["qualify", "qualified", "qualifier", "qualification"], correctIndex: 3, explanation: "'Qualification' là danh từ của 'qualify' (hậu tố '-tion'), nghĩa 'bằng cấp/chứng chỉ'. Sau mạo từ 'a', câu cần danh từ làm tân ngữ của 'has'. 'Qualified' là tính từ (nghĩa 'có đủ trình độ/được cấp phép') nên không thể đứng sau 'a' ở vị trí danh từ." },
  { id: "n101", question: "The _____ of the survey were released this morning. (find)", options: ["find", "found", "finder", "findings"], correctIndex: 3, explanation: "'Findings' (số nhiều, hậu tố '-ings') là danh từ của 'find', nghĩa 'kết quả nghiên cứu/khảo sát'. Động từ 'were' ở số nhiều xác nhận chủ ngữ phải là danh từ số nhiều này. 'Finder' là danh từ chỉ người/vật tìm ra (số ít, chỉ người), không khớp cả về số lượng lẫn nghĩa." },
  { id: "n102", question: "Her _____ in the company started as an internship. (employ)", options: ["employ", "employer", "employed", "employment"], correctIndex: 3, explanation: "'Employment' là danh từ của 'employ' (hậu tố '-ment'), nghĩa 'việc làm/quá trình làm việc', đứng sau 'Her' làm chủ ngữ. 'Employer' là danh từ chỉ người sử dụng lao động (khác hẳn với chủ ngữ 'cô ấy' là người đi làm), nên không khớp nghĩa câu." },
  { id: "n103", question: "The _____ of goods across borders requires customs clearance. (move)", options: ["move", "moved", "mover", "movement"], correctIndex: 3, explanation: "'Movement' là danh từ của 'move' (hậu tố '-ment'), nghĩa 'sự di chuyển/vận chuyển', đứng sau 'The' làm chủ ngữ. 'Mover' là danh từ chỉ người/công ty vận chuyển (chủ thể), không phải bản thân hành động di chuyển hàng hóa nên không khớp nghĩa." },
  { id: "n104", question: "There was a _____ in communication during the merger. (break down)", options: ["breaking", "breakdown", "broke", "broken"], correctIndex: 1, explanation: "'Breakdown' là danh từ ghép (từ 'break' và 'down'), nghĩa 'sự cố/đổ vỡ', đứng sau mạo từ 'a' làm chủ ngữ thực. 'Breaking' (V-ing) là dạng động danh từ ít tự nhiên hơn hẳn so với danh từ ghép chuẩn 'breakdown' trong cụm cố định 'a breakdown in communication'." },
  { id: "n105", question: "The _____ of the school was excellent. (reputate)", options: ["reputate", "reputed", "reputably", "reputation"], correctIndex: 3, explanation: "'Reputation' là danh từ (liên quan đến 'reputed'/'repute'), nghĩa 'danh tiếng', đứng sau 'The' làm chủ ngữ. 'Reputed' là tính từ/phân từ (nghĩa 'được cho là, nổi tiếng là') nên không thể tự làm chủ ngữ đứng một mình ở đây." },
  { id: "n106", question: "She gave a _____ to charity every year. (donate)", options: ["donate", "donated", "donating", "donation"], correctIndex: 3, explanation: "'Donation' là danh từ của 'donate' (hậu tố '-tion'), dùng trong cụm 'give a donation'. Sau mạo từ 'a', câu cần danh từ làm tân ngữ của 'gave'. 'Donating' (V-ing) không tự nhiên bằng danh từ chuẩn 'donation' sau mạo từ 'a' trong cấu trúc này." },
  { id: "n107", question: "The _____ of the project was delayed by bad weather. (complete)", options: ["complete", "completed", "completely", "completion"], correctIndex: 3, explanation: "'Completion' là danh từ của 'complete' (hậu tố '-tion'), nghĩa 'sự hoàn thành', đứng sau 'The' làm chủ ngữ. 'Completely' là trạng từ (hậu tố '-ly') nên không thể làm chủ ngữ đứng sau 'The' được." },
  { id: "n108", question: "His _____ of the book was insightful. (review)", options: ["review", "reviewed", "reviewer", "revue"], correctIndex: 0, explanation: "'Review' vừa là động từ vừa là danh từ (nghĩa 'bài đánh giá/nhận xét'), ở đây đứng sau sở hữu cách 'His' làm chủ ngữ nên đóng vai trò danh từ. 'Reviewer' là danh từ chỉ người viết đánh giá (con người), khác với bản thân bài viết nên không khớp nghĩa - còn 'revue' là từ khác nghĩa hoàn toàn (một loại chương trình tạp kỹ)." },
  { id: "n109", question: "She had a _____ feeling that something was wrong. (premonish)", options: ["premonition", "premonish", "premonishly", "premonished"], correctIndex: 0, explanation: "'Premonition' là danh từ chỉ 'linh cảm', đứng sau mạo từ 'a' để bổ nghĩa cho danh từ 'feeling' (cụm 'a premonition feeling'). 'Premonished' và 'premonishly' thực ra không phải các từ chuẩn trong tiếng Anh, chỉ 'premonition' mới đúng chính tả và đúng từ loại danh từ cần thiết ở đây." },
  { id: "n110", question: "The _____ of the report takes priority. (accurate)", options: ["accurately", "accurate", "accuracy", "accurateness"], correctIndex: 2, explanation: "'Accuracy' là danh từ của tính từ 'accurate' (hậu tố '-acy'), nghĩa 'độ chính xác', đứng sau 'The' làm chủ ngữ. 'Accurately' là trạng từ (hậu tố '-ly') nên không thể làm chủ ngữ đứng sau 'The' được; 'accurateness' tuy có cấu tạo giống danh từ nhưng ít dùng hơn hẳn 'accuracy' trong tiếng Anh chuẩn." },
  { id: "n111", question: "She made a _____ to visit her parents every weekend. (commit)", options: ["commit", "committing", "committer", "commitment"], correctIndex: 3, explanation: "'Commitment' là danh từ của 'commit' (hậu tố '-ment'), dùng trong cụm 'make a commitment to'. Sau mạo từ 'a', câu cần danh từ làm tân ngữ của 'made'. 'Committer' là danh từ hiếm dùng, mang nghĩa người thực hiện, không tự nhiên bằng 'commitment' để chỉ lời cam kết." },
  { id: "n112", question: "The _____ between supply and demand affects pricing. (balance)", options: ["balance", "balanced", "balancing", "balancer"], correctIndex: 0, explanation: "'Balance' vừa là động từ vừa là danh từ (nghĩa 'sự cân bằng'), ở đây đứng sau 'The' làm chủ ngữ trong cụm 'balance between X and Y'. 'Balanced' là tính từ/phân từ (nghĩa 'cân bằng, cân đối') nên không thể tự làm chủ ngữ đứng một mình được." },
  { id: "n113", question: "We need more _____ to fund the research program. (invest)", options: ["invest", "invested", "investor", "investment"], correctIndex: 3, explanation: "'Investment' là danh từ của 'invest' (hậu tố '-ment'), nghĩa 'khoản đầu tư/nguồn vốn'. Sau lượng từ 'more', câu cần danh từ làm tân ngữ của 'need'. 'Investor' là danh từ chỉ người đầu tư (con người), không phải bản thân khoản tiền/nguồn lực nên không khớp nghĩa câu." },
  { id: "n114", question: "The _____ of the ancient ruins attracted many tourists. (discover)", options: ["discover", "discoverer", "discovered", "discovery"], correctIndex: 3, explanation: "'Discovery' là danh từ của 'discover' (đổi '-er' thành '-y'), nghĩa 'sự phát hiện', đứng sau 'The' làm chủ ngữ. 'Discoverer' là danh từ chỉ người phát hiện ra (con người cụ thể), không phải bản thân phát hiện đó, nên không hợp nghĩa 'thu hút nhiều khách du lịch'." },
  { id: "n115", question: "There has been a significant _____ in air quality. (deteriorate)", options: ["deteriorate", "deteriorating", "deteriorator", "deterioration"], correctIndex: 3, explanation: "'Deterioration' là danh từ của 'deteriorate' (hậu tố '-ation'), nghĩa 'sự xuống cấp/suy giảm'. Sau tính từ 'significant', câu cần danh từ làm chủ ngữ thực trong cấu trúc 'there has been'. 'Deteriorating' là tính từ/phân từ (nghĩa 'đang xuống cấp') nên không đứng được ở vị trí danh từ này." },
  { id: "n116", question: "She showed great _____ in her approach to the new role. (adapt)", options: ["adapt", "adaptable", "adapter", "adaptability"], correctIndex: 3, explanation: "'Adaptability' là danh từ của tính từ 'adaptable' (gốc 'adapt', hậu tố '-ility'), nghĩa 'khả năng thích nghi'. Sau tính từ 'great', câu cần danh từ làm tân ngữ của 'showed'. 'Adaptable' chính nó là tính từ (nghĩa 'có khả năng thích nghi') nên không thể đứng sau 'great' ở vị trí danh từ." },
  { id: "n117", question: "The government made a _____ to reduce carbon emissions. (pledge)", options: ["pledge", "pledging", "pledgee", "pledgeable"], correctIndex: 0, explanation: "'Pledge' vừa là động từ vừa là danh từ (nghĩa 'lời cam kết'), dùng trong cụm 'make a pledge to'. Sau mạo từ 'a', câu cần danh từ làm tân ngữ của 'made'. 'Pledging' (V-ing) không tự nhiên bằng danh từ 'pledge' trong cụm cố định này." },
  { id: "n118", question: "Her _____ in photography won her several awards. (expert)", options: ["expert", "expertly", "expertness", "expertise"], correctIndex: 3, explanation: "'Expertise' là danh từ liên quan đến tính từ 'expert' (thêm '-ise'), nghĩa 'sự thành thạo/chuyên môn sâu'. Sau 'Her' làm chủ ngữ, câu cần danh từ. 'Expertly' là trạng từ (hậu tố '-ly', nghĩa 'một cách thành thạo') nên không thể làm chủ ngữ đứng sau 'Her'." },
  { id: "n119", question: "The _____ of the new CEO sparked investor interest. (appoint)", options: ["appoint", "appointee", "appointer", "appointment"], correctIndex: 3, explanation: "'Appointment' là danh từ của 'appoint' (hậu tố '-ment'), nghĩa 'sự bổ nhiệm', đứng sau 'The' làm chủ ngữ. 'Appointee' là danh từ chỉ người được bổ nhiệm (chính vị CEO mới), khác với 'sự kiện bổ nhiệm' - chủ thể 'gây chú ý cho nhà đầu tư' phải là sự kiện chứ không phải con người." },
  { id: "n120", question: "She had no _____ of starting over in a new city. (intend)", options: ["intend", "intended", "intending", "intention"], correctIndex: 3, explanation: "'Intention' là danh từ của 'intend' (hậu tố '-tion'), dùng trong cụm 'have no intention of'. Sau 'no', câu cần danh từ làm tân ngữ của 'had'. 'Intended' là tính từ/phân từ (nghĩa 'được dự định') nên không thể đứng sau 'no' ở vị trí danh từ này." },
  { id: "n121", question: "The _____ of the project to different departments was fair. (allot)", options: ["allot", "allotted", "alloter", "allotment"], correctIndex: 3, explanation: "'Allotment' là danh từ của 'allot' (hậu tố '-ment'), nghĩa 'sự phân bổ', đứng sau 'The' làm chủ ngữ. 'Allotted' là tính từ/phân từ (nghĩa 'đã được phân bổ') nên không thể tự làm chủ ngữ đứng một mình ở đây." },
  { id: "n122", question: "There was a _____ in the service due to technical issues. (disrupt)", options: ["disrupt", "disrupted", "disruptive", "disruption"], correctIndex: 3, explanation: "'Disruption' là danh từ của 'disrupt' (hậu tố '-tion'), nghĩa 'sự gián đoạn', đứng sau mạo từ 'a' làm chủ ngữ thực. 'Disruptive' là tính từ (nghĩa 'gây gián đoạn, gây rối') nên không thể đứng sau 'a' ở vị trí danh từ này." },
  { id: "n123", question: "She has a strong _____ for classical music. (passionate)", options: ["passionate", "passionately", "passionateness", "passion"], correctIndex: 3, explanation: "'Passion' là danh từ gốc (tính từ 'passionate' được tạo từ nó bằng hậu tố '-ate'), nghĩa 'niềm đam mê', dùng trong cụm 'a passion for'. Sau tính từ 'strong', câu cần danh từ làm tân ngữ của 'has'. 'Passionately' là trạng từ (hậu tố '-ly') nên không thể đứng ở vị trí danh từ này." },
  { id: "n124", question: "The _____ of the new tax was met with public protests. (introduce)", options: ["introduce", "introduced", "introducer", "introduction"], correctIndex: 3, explanation: "'Introduction' là danh từ của 'introduce' (hậu tố '-tion'), nghĩa 'sự ra mắt/đưa vào áp dụng', đứng sau 'The' làm chủ ngữ. 'Introducer' ít dùng, chỉ người giới thiệu (con người), không phù hợp với chủ ngữ là 'việc ban hành thuế mới' trong câu." },
  { id: "n125", question: "She values _____ above everything else in a relationship. (honest)", options: ["honest", "honestly", "honesty", "honestness"], correctIndex: 2, explanation: "'Honesty' là danh từ của tính từ 'honest' (đổi thành '-y'), nghĩa 'sự trung thực', làm tân ngữ của động từ 'values'. Vị trí sau động từ này cần một danh từ cụ thể. 'Honestly' là trạng từ (hậu tố '-ly', nghĩa 'một cách thành thật') nên không thể làm tân ngữ ở đây." },
  { id: "n126", question: "The _____ between the two siblings was difficult to resolve. (conflict)", options: ["conflict", "conflicting", "conflicted", "confliction"], correctIndex: 0, explanation: "'Conflict' vừa là danh từ vừa là động từ (nghĩa 'mâu thuẫn'), ở đây đứng sau 'The' làm chủ ngữ trong cụm 'conflict between X and Y'. 'Conflicting' là tính từ/phân từ (nghĩa 'mâu thuẫn nhau', bổ nghĩa cho danh từ khác như 'conflicting opinions') nên không thể tự làm chủ ngữ đứng một mình." },
  { id: "n127", question: "She has a unique _____ for spotting trends. (able)", options: ["able", "ability", "ably", "ableness"], correctIndex: 1, explanation: "'Ability' là danh từ của tính từ 'able' (hậu tố '-ity'), nghĩa 'khả năng', dùng trong cụm 'ability for/to'. Sau tính từ 'unique', câu cần danh từ làm tân ngữ của 'has'. 'Ably' là trạng từ (hậu tố '-ly') nên không thể đứng ở vị trí danh từ này." },
  { id: "n128", question: "The new software resulted in a huge _____ in productivity. (increase)", options: ["increase", "increasing", "increaser", "increased"], correctIndex: 0, explanation: "'Increase' vừa là động từ vừa là danh từ (nghĩa 'sự gia tăng'), đứng sau tính từ 'huge' trong cụm 'an increase in productivity'. 'Increasing' là tính từ/phân từ (nghĩa 'đang gia tăng', dùng bổ nghĩa cho danh từ khác) nên không thể đứng sau mạo từ và tính từ ở vị trí danh từ chính này." },
  { id: "n129", question: "She built a strong _____ in the industry through her work. (reputate)", options: ["reputate", "reputed", "reputably", "reputation"], correctIndex: 3, explanation: "'Reputation' là danh từ chỉ 'danh tiếng', dùng trong cụm 'build a reputation'. Sau tính từ 'strong', câu cần danh từ làm tân ngữ của 'built'. 'Reputed' là tính từ/phân từ (nghĩa 'được cho là, nổi danh là') nên không thể đứng sau 'strong' ở vị trí danh từ." },
  { id: "n130", question: "The _____ of funds to the new department was approved. (allocate)", options: ["allocate", "allocated", "allocating", "allocation"], correctIndex: 3, explanation: "'Allocation' là danh từ của 'allocate' (hậu tố '-ation'), nghĩa 'sự phân bổ', đứng sau 'The' làm chủ ngữ. 'Allocating' (V-ing) không tự nhiên bằng danh từ chuẩn 'allocation' để làm chủ ngữ chính thức trong câu này." },
  { id: "n131", question: "Her _____ on punctuality is well-known. (insist)", options: ["insist", "insisted", "insistence", "insisting"], correctIndex: 2, explanation: "'Insistence' là danh từ của 'insist' (hậu tố '-ence'), nghĩa 'sự khăng khăng, kiên quyết', dùng trong cụm 'insistence on'. Sau 'Her' làm chủ ngữ, câu cần danh từ. 'Insisted' là dạng quá khứ của động từ nên không thể đóng vai trò danh từ chủ ngữ ở đây." },
  { id: "n132", question: "The _____ of the school was established 100 years ago. (found)", options: ["found", "founder", "foundation", "foundling"], correctIndex: 2, explanation: "'Foundation' là danh từ của 'found' (hậu tố '-ation'), nghĩa 'sự thành lập', đứng sau 'The' làm chủ ngữ. 'Founder' là danh từ chỉ người sáng lập (con người), khác với 'sự thành lập' là sự kiện/hành động nên không khớp nghĩa 'được thành lập cách đây 100 năm'." },
  { id: "n133", question: "She had a clear _____ of what she wanted to achieve. (visual)", options: ["visual", "visually", "visibility", "vision"], correctIndex: 3, explanation: "'Vision' là danh từ gốc (tính từ 'visual' được tạo từ nó), nghĩa 'tầm nhìn/hình dung', dùng trong cụm 'have a vision of'. Sau tính từ 'clear', câu cần danh từ làm tân ngữ của 'had'. 'Visibility' tuy cũng là danh từ nhưng nghĩa là 'tầm nhìn xa/độ rõ' (về mặt vật lý), không hợp nghĩa 'hình dung về điều muốn đạt được'." },
  { id: "n134", question: "His _____ of the market was extremely accurate. (assess)", options: ["assess", "assessed", "assessor", "assessment"], correctIndex: 3, explanation: "'Assessment' là danh từ của 'assess' (hậu tố '-ment'), nghĩa 'sự đánh giá', đứng sau 'His' làm chủ ngữ. 'Assessor' là danh từ chỉ người đánh giá/thẩm định viên (con người), không phải bản thân nhận định về thị trường nên không khớp nghĩa." },
  { id: "n135", question: "There was no _____ between what he said and what he did. (consistent)", options: ["consistent", "consistently", "consistency", "consist"], correctIndex: 2, explanation: "'Consistency' là danh từ của tính từ 'consistent' (hậu tố '-ency'), nghĩa 'sự nhất quán', dùng trong cụm 'consistency between'. Sau 'no', câu cần danh từ làm chủ ngữ thực trong cấu trúc 'there was'. 'Consistently' là trạng từ (hậu tố '-ly') nên không thể đứng ở vị trí danh từ này." },
  { id: "n136", question: "The _____ in infrastructure has boosted economic growth. (invest)", options: ["invest", "investor", "investing", "investment"], correctIndex: 3, explanation: "'Investment' là danh từ của 'invest' (hậu tố '-ment'), dùng trong cụm 'investment in infrastructure'. Sau 'The' làm chủ ngữ, câu cần danh từ. 'Investor' là danh từ chỉ người đầu tư (con người), khác với 'khoản đầu tư' nên không khớp nghĩa 'thúc đẩy tăng trưởng kinh tế'." },
  { id: "n137", question: "She received a formal _____ to the ceremony. (invite)", options: ["invite", "inviting", "inviter", "invitation"], correctIndex: 3, explanation: "'Invitation' là danh từ của 'invite' (hậu tố '-ation'), nghĩa 'lời mời', đứng sau tính từ 'formal' làm tân ngữ của 'received'. 'Inviting' là tính từ/phân từ (nghĩa 'hấp dẫn, mời gọi', như trong 'an inviting smell') nên không hợp nghĩa và vị trí ở đây." },
  { id: "n138", question: "The _____ of the plan will require careful monitoring. (execute)", options: ["execute", "executed", "executor", "execution"], correctIndex: 3, explanation: "'Execution' là danh từ của 'execute' (hậu tố '-tion'), nghĩa 'sự thực thi', đứng sau 'The' làm chủ ngữ. 'Executor' là danh từ chỉ người thực thi (con người, đặc biệt trong luật di chúc), không phải bản thân quá trình thực hiện kế hoạch nên không khớp nghĩa." },
  { id: "n139", question: "There was a clear _____ of roles within the team. (divide)", options: ["divide", "dividing", "divisive", "division"], correctIndex: 3, explanation: "'Division' là danh từ của 'divide' (hậu tố '-sion'), nghĩa 'sự phân chia', dùng trong cụm 'division of roles'. Sau tính từ 'clear', câu cần danh từ làm chủ ngữ thực. 'Divisive' là tính từ (nghĩa 'gây chia rẽ') nên không thể đứng sau 'clear' ở vị trí danh từ này." },
  { id: "n140", question: "She has a remarkable _____ for numbers. (able)", options: ["able", "ably", "ableness", "ability"], correctIndex: 3, explanation: "'Ability' là danh từ của tính từ 'able' (hậu tố '-ity'), dùng trong cụm 'ability for numbers'. Sau tính từ 'remarkable', câu cần danh từ làm tân ngữ của 'has'. 'Ably' là trạng từ (hậu tố '-ly') nên không thể đứng ở vị trí danh từ này." },
  { id: "n141", question: "The government made a formal _____ of independence. (declare)", options: ["declare", "declared", "declarative", "declaration"], correctIndex: 3, explanation: "'Declaration' là danh từ của 'declare' (hậu tố '-ation'), dùng trong cụm 'make a declaration'. Sau tính từ 'formal', câu cần danh từ làm tân ngữ của 'made'. 'Declarative' là tính từ (thuật ngữ ngữ pháp, nghĩa 'thuộc câu trần thuật') nên không hợp vị trí danh từ ở đây." },
  { id: "n142", question: "He showed real _____ for the feelings of others. (consider)", options: ["consider", "considered", "considerably", "consideration"], correctIndex: 3, explanation: "'Consideration' là danh từ của 'consider' (hậu tố '-ation'), dùng trong cụm 'show consideration for'. Sau tính từ 'real', câu cần danh từ làm tân ngữ của 'showed'. 'Considerably' là trạng từ (hậu tố '-ly', nghĩa 'đáng kể') nên không thể đứng ở vị trí danh từ này." },
  { id: "n143", question: "The _____ of the treaty ended the war. (sign)", options: ["sign", "signed", "signer", "signing"], correctIndex: 3, explanation: "'Signing' là danh từ hóa từ động từ 'sign' bằng dạng V-ing, nghĩa 'lễ ký kết', đứng sau 'The' làm chủ ngữ. 'Signer' là danh từ chỉ người ký (con người), không phải bản thân sự kiện ký kết đã 'kết thúc chiến tranh' nên không khớp nghĩa." },
  { id: "n144", question: "She gained valuable _____ during her internship. (expose)", options: ["expose", "exposed", "exposing", "exposure"], correctIndex: 3, explanation: "'Exposure' là danh từ của 'expose' (hậu tố '-ure'), nghĩa 'sự tiếp xúc/trải nghiệm thực tế', dùng trong cụm 'gain exposure'. Sau tính từ 'valuable', câu cần danh từ làm tân ngữ của 'gained'. 'Exposed' là tính từ/phân từ (nghĩa 'bị phơi bày, tiếp xúc') nên không thể đứng ở vị trí danh từ này." },
  { id: "n145", question: "The _____ of the new system exceeded expectations. (perform)", options: ["perform", "performer", "performed", "performance"], correctIndex: 3, explanation: "'Performance' là danh từ của 'perform' (hậu tố '-ance'), ở đây nghĩa 'hiệu suất hoạt động', đứng sau 'The' làm chủ ngữ. 'Performer' là danh từ chỉ người biểu diễn (con người), không hợp nghĩa khi nói về hiệu suất của 'hệ thống mới'." },
  { id: "n146", question: "She expressed her _____ at the committee's poor decision. (frustrate)", options: ["frustrate", "frustrated", "frustrating", "frustration"], correctIndex: 3, explanation: "'Frustration' là danh từ của 'frustrate' (hậu tố '-tion'), nghĩa 'sự bực bội/thất vọng', đứng sau 'her' làm tân ngữ của 'expressed'. 'Frustrated' là tính từ (nghĩa 'cảm thấy bực bội', mô tả người) nên không thể đứng sau sở hữu cách ở vị trí danh từ này." },
  { id: "n147", question: "The _____ in customer service led to many complaints. (fail)", options: ["fail", "failing", "failed", "failure"], correctIndex: 3, explanation: "'Failure' là danh từ của 'fail' (hậu tố '-ure'), dùng trong cụm 'failure in customer service'. Sau 'The' làm chủ ngữ, câu cần danh từ. 'Failing' tuy có thể làm danh từ số nhiều nghĩa 'khuyết điểm' nhưng ở dạng số ít này 'failure' mới là lựa chọn tự nhiên và chuẩn xác." },
  { id: "n148", question: "Her _____ was evident in every detail of her work. (dedicate)", options: ["dedicate", "dedicated", "dedicating", "dedication"], correctIndex: 3, explanation: "'Dedication' là danh từ của 'dedicate' (hậu tố '-tion'), nghĩa 'sự tận tâm', đứng sau 'Her' làm chủ ngữ. 'Dedicated' là tính từ/phân từ (nghĩa 'tận tâm, chuyên tâm', mô tả người) nên không thể đứng sau sở hữu cách ở vị trí danh từ chủ ngữ này." },
  { id: "n149", question: "The _____ of digital technology is changing education. (emerge)", options: ["emerge", "emerged", "emerging", "emergence"], correctIndex: 3, explanation: "'Emergence' là danh từ của 'emerge' (hậu tố '-ence'), nghĩa 'sự xuất hiện/nổi lên', đứng sau 'The' làm chủ ngữ. 'Emerging' là tính từ/phân từ (nghĩa 'đang nổi lên', như trong 'emerging technology') nên không thể tự làm chủ ngữ đứng một mình ở đây." },
  { id: "n150", question: "She built her _____ on hard work and integrity. (reputate)", options: ["reputate", "reputably", "reputed", "reputation"], correctIndex: 3, explanation: "'Reputation' là danh từ chỉ 'danh tiếng', dùng trong cụm 'build a reputation on'. Sau sở hữu cách 'her', câu cần danh từ làm tân ngữ của 'built'. 'Reputed' là tính từ/phân từ (nghĩa 'được cho là, nổi danh là') nên không thể đứng sau 'her' ở vị trí danh từ." },
  { id: "n151", question: "The _____ of funds was carefully tracked. (distribute)", options: ["distribute", "distributing", "distributor", "distribution"], correctIndex: 3, explanation: "'Distribution' là danh từ của 'distribute' (hậu tố '-tion'), nghĩa 'việc phân phối', đứng sau 'The' làm chủ ngữ. 'Distributor' là danh từ chỉ nhà phân phối (con người/tổ chức), không phải bản thân quá trình phân phối được 'theo dõi cẩn thận' nên không khớp nghĩa." },
  { id: "n152", question: "She felt a deep _____ to serve her community. (oblige)", options: ["oblige", "obliged", "obliging", "obligation"], correctIndex: 3, explanation: "'Obligation' là danh từ của 'oblige' (hậu tố '-ation'), nghĩa 'nghĩa vụ', dùng trong cụm 'a deep obligation to'. Sau tính từ 'deep', câu cần danh từ làm tân ngữ của 'felt'. 'Obliging' là tính từ (nghĩa 'sẵn lòng giúp đỡ') nên không hợp nghĩa và vị trí ở đây." },
  { id: "n153", question: "The _____ of greenhouse gases is a global concern. (emit)", options: ["emit", "emitting", "emitter", "emission"], correctIndex: 3, explanation: "'Emission' là danh từ của 'emit' (hậu tố '-sion'), nghĩa 'sự phát thải', dùng trong cụm 'emission of greenhouse gases'. Sau 'The' làm chủ ngữ, câu cần danh từ. 'Emitter' là danh từ chỉ vật/nguồn phát thải (chủ thể), không phải bản thân hành động phát thải là 'mối quan tâm toàn cầu' nên không khớp nghĩa." },
  { id: "n154", question: "Her _____ to the cause inspired many followers. (devote)", options: ["devote", "devoted", "devotedly", "devotion"], correctIndex: 3, explanation: "'Devotion' là danh từ của 'devote' (hậu tố '-tion'), nghĩa 'sự tận tụy/hết lòng', đứng sau 'Her' làm chủ ngữ. 'Devoted' là tính từ/phân từ (nghĩa 'tận tụy, hết lòng', mô tả người) nên không thể đứng sau sở hữu cách ở vị trí danh từ này." },
  { id: "n155", question: "The _____ of the ancient manuscript is still debated. (authentic)", options: ["authentic", "authentically", "authenticate", "authenticity"], correctIndex: 3, explanation: "'Authenticity' là danh từ của tính từ 'authentic' (hậu tố '-ity'), nghĩa 'tính xác thực', đứng sau 'The' làm chủ ngữ. 'Authenticate' là động từ (nghĩa 'xác thực, chứng thực') nên không thể đứng sau 'The' ở vị trí danh từ chủ ngữ này." },
  { id: "n156", question: "He had no _____ of quitting despite the setbacks. (intend)", options: ["intend", "intended", "intender", "intention"], correctIndex: 3, explanation: "'Intention' là danh từ của 'intend' (hậu tố '-tion'), dùng trong cụm 'have no intention of'. Sau 'no', câu cần danh từ làm tân ngữ của 'had'. 'Intended' là tính từ/phân từ (nghĩa 'được dự định') nên không thể đứng sau 'no' ở vị trí danh từ này." },
  { id: "n157", question: "The _____ of the bill requires a majority vote. (pass)", options: ["pass", "passed", "passer", "passage"], correctIndex: 3, explanation: "'Passage' là danh từ của 'pass' (hậu tố '-age'), ở đây nghĩa 'việc thông qua (một dự luật)', đứng sau 'The' làm chủ ngữ. 'Passer' là danh từ chỉ người đi ngang qua/vượt qua (nghĩa hoàn toàn khác), không liên quan đến việc một dự luật được thông qua trong Quốc hội." },
  { id: "n158", question: "She showed an impressive _____ of foreign cultures. (understand)", options: ["understand", "understood", "understandable", "understanding"], correctIndex: 3, explanation: "'Understanding' là danh từ hóa của 'understand' bằng dạng V-ing, nghĩa 'sự am hiểu', dùng trong cụm 'understanding of cultures'. Sau tính từ 'impressive', câu cần danh từ làm tân ngữ của 'showed'. 'Understandable' là tính từ (nghĩa 'có thể hiểu được') nên không thể đứng ở vị trí danh từ này." },
  { id: "n159", question: "The _____ of the two organizations took several months. (integrate)", options: ["integrate", "integrating", "integrator", "integration"], correctIndex: 3, explanation: "'Integration' là danh từ của 'integrate' (hậu tố '-tion'), nghĩa 'sự hợp nhất', đứng sau 'The' làm chủ ngữ. 'Integrator' là danh từ chỉ người/hệ thống thực hiện tích hợp (chủ thể), không phải bản thân quá trình hợp nhất kéo dài 'nhiều tháng' nên không khớp nghĩa." },
  { id: "n160", question: "There is growing _____ that climate change is accelerating. (evident)", options: ["evident", "evidently", "evidential", "evidence"], correctIndex: 3, explanation: "'Evidence' là danh từ (tính từ 'evident' được tạo từ nó), nghĩa 'bằng chứng', dùng trong cụm 'growing evidence that'. Sau tính từ 'growing', câu cần danh từ làm chủ ngữ thực trong cấu trúc 'there is'. 'Evidently' là trạng từ (hậu tố '-ly', nghĩa 'rõ ràng là') nên không thể đứng ở vị trí danh từ này." },
  { id: "n161", question: "The teacher praised her _____ in completing the assignment. (thorough)", options: ["thorough", "thoroughly", "thoroughness", "thorougher"], correctIndex: 2, explanation: "'Thoroughness' là danh từ trừu tượng của tính từ 'thorough' (hậu tố '-ness'), nghĩa 'sự tỉ mỉ, kỹ lưỡng'. Sau sở hữu cách 'her', câu cần danh từ làm tân ngữ của 'praised'. 'Thoroughly' là trạng từ (hậu tố '-ly') nên không thể đứng sau 'her' ở vị trí danh từ." },
  { id: "n162", question: "The company plans a major _____ of its product line. (expand)", options: ["expand", "expanded", "expanding", "expansion"], correctIndex: 3, explanation: "'Expansion' là danh từ của 'expand' (hậu tố '-sion'), dùng trong cụm 'a major expansion of'. Sau tính từ 'major', câu cần danh từ làm tân ngữ của 'plans'. 'Expanding' là tính từ/phân từ (nghĩa 'đang mở rộng') nên không thể đứng sau mạo từ và tính từ ở vị trí danh từ chính này." },
  { id: "n163", question: "The _____ of the new drug showed promising results. (test)", options: ["test", "testing", "tested", "tester"], correctIndex: 1, explanation: "'Testing' là danh từ hóa của 'test' bằng dạng V-ing, nghĩa 'việc thử nghiệm', đứng sau 'The' làm chủ ngữ. 'Tester' là danh từ chỉ người/thiết bị thử nghiệm (chủ thể), không phải bản thân quá trình thử nghiệm 'cho kết quả khả quan' nên không khớp nghĩa." },
  { id: "n164", question: "He had a _____ that the project would succeed. (convict)", options: ["convict", "convicted", "convicting", "conviction"], correctIndex: 3, explanation: "'Conviction' là danh từ của 'convict' (hậu tố '-tion'), ở đây nghĩa 'niềm tin chắc chắn', dùng trong cụm 'a conviction that'. Sau mạo từ 'a', câu cần danh từ làm tân ngữ của 'had'. 'Convicted' là tính từ/phân từ (nghĩa 'bị kết án', hoàn toàn khác nghĩa) nên không thể đứng sau 'a' ở vị trí danh từ." },
  { id: "n165", question: "She felt a sense of _____ after completing the marathon. (accomplish)", options: ["accomplish", "accomplished", "accomplishing", "accomplishment"], correctIndex: 3, explanation: "'Accomplishment' là danh từ của 'accomplish' (hậu tố '-ment'), dùng trong cụm 'sense of accomplishment'. Sau giới từ 'of', câu cần danh từ. 'Accomplished' là tính từ (nghĩa 'thành đạt, tài giỏi', mô tả người) nên không thể đứng sau 'of' ở vị trí danh từ này." },
  { id: "n166", question: "The _____ of a new hospital will benefit the community. (establish)", options: ["establish", "established", "establishing", "establishment"], correctIndex: 3, explanation: "'Establishment' là danh từ của 'establish' (hậu tố '-ment'), nghĩa 'sự thành lập', đứng sau 'The' làm chủ ngữ. 'Established' là tính từ/phân từ (nghĩa 'đã được thành lập, có uy tín') nên không thể tự làm chủ ngữ đứng một mình được." },
  { id: "n167", question: "There was a sudden _____ in the stock market. (collapse)", options: ["collapse", "collapsing", "collapsible", "collapsed"], correctIndex: 0, explanation: "'Collapse' vừa là động từ vừa là danh từ (nghĩa 'sự sụp đổ'), đứng sau tính từ 'sudden' làm chủ ngữ thực trong cấu trúc 'there was'. 'Collapsible' là tính từ (nghĩa 'có thể gấp/xếp lại được', dùng cho đồ vật) nên hoàn toàn không phù hợp nghĩa và vị trí ở đây." },
  { id: "n168", question: "She submitted her _____ for the design competition. (enter)", options: ["enter", "entered", "entering", "entry"], correctIndex: 3, explanation: "'Entry' là danh từ của 'enter' (đổi thành '-y'), nghĩa 'bài dự thi', dùng trong cụm 'submit an entry'. Sau sở hữu cách 'her', câu cần danh từ làm tân ngữ của 'submitted'. 'Entering' (V-ing) không tự nhiên bằng danh từ chuẩn 'entry' để chỉ tác phẩm dự thi cụ thể." },
  { id: "n169", question: "The _____ of the policy change was poorly handled. (communicate)", options: ["communicate", "communicated", "communicator", "communication"], correctIndex: 3, explanation: "'Communication' là danh từ của 'communicate' (hậu tố '-tion'), nghĩa 'việc truyền đạt thông tin', đứng sau 'The' làm chủ ngữ. 'Communicator' là danh từ chỉ người truyền đạt (con người), không phải bản thân quá trình truyền đạt bị 'xử lý kém' nên không khớp nghĩa." },
  { id: "n170", question: "His _____ in the field of robotics is unmatched. (expert)", options: ["expert", "expertly", "experted", "expertise"], correctIndex: 3, explanation: "'Expertise' là danh từ liên quan đến 'expert' (thêm '-ise'), nghĩa 'sự chuyên môn sâu', đứng sau 'His' làm chủ ngữ. 'Expertly' là trạng từ (hậu tố '-ly') nên không thể làm chủ ngữ đứng sau 'His'; 'experted' cũng không phải một từ chuẩn trong tiếng Anh." },
  { id: "n171", question: "The _____ between the two cultures was a fascinating study. (differ)", options: ["differ", "different", "differently", "difference"], correctIndex: 3, explanation: "'Difference' là danh từ của 'differ' (hậu tố '-ence'), dùng trong cụm 'difference between'. Sau 'The' làm chủ ngữ, câu cần danh từ. 'Different' là tính từ (nghĩa 'khác nhau') nên không thể tự làm chủ ngữ đứng sau 'The' được." },
  { id: "n172", question: "She received the highest _____ in the entire department. (perform)", options: ["perform", "performer", "performing", "performance"], correctIndex: 3, explanation: "'Performance' là danh từ của 'perform' (hậu tố '-ance'), ở đây nghĩa 'thành tích/kết quả công việc', đứng sau tính từ 'highest' làm tân ngữ của 'received'. 'Performer' là danh từ chỉ người biểu diễn (con người), không hợp nghĩa 'thành tích cao nhất phòng ban' ở đây." },
  { id: "n173", question: "The _____ of the problem was beyond our control. (complex)", options: ["complex", "complexly", "complexion", "complexity"], correctIndex: 3, explanation: "'Complexity' là danh từ trừu tượng của tính từ 'complex' (hậu tố '-ity'), nghĩa 'tính phức tạp', đứng sau 'The' làm chủ ngữ. 'Complexion' tuy trông giống nhưng lại là từ khác nghĩa hoàn toàn (nghĩa 'làn da mặt'), nên không thể nhầm lẫn dùng ở đây dù có hình thức gần giống." },
  { id: "n174", question: "She has great _____ in choosing the right words. (precise)", options: ["precise", "precisely", "precision", "preciseness"], correctIndex: 2, explanation: "'Precision' là danh từ của tính từ 'precise' (đổi thành '-ion'), nghĩa 'sự chính xác', dùng trong cụm 'precision in choosing'. Sau tính từ 'great', câu cần danh từ làm tân ngữ của 'has'. 'Precisely' là trạng từ (hậu tố '-ly') nên không thể đứng ở vị trí danh từ này." },
  { id: "n175", question: "The _____ of the results confirmed the initial hypothesis. (analyze)", options: ["analyze", "analyzed", "analyzer", "analysis"], correctIndex: 3, explanation: "'Analysis' là danh từ của 'analyze' (đổi đuôi thành '-sis'), nghĩa 'sự phân tích', dùng trong cụm 'analysis of results'. Sau 'The' làm chủ ngữ, câu cần danh từ. 'Analyzer' là danh từ chỉ người/công cụ phân tích (chủ thể), không phải bản thân kết quả phân tích 'khẳng định giả thuyết ban đầu' nên không khớp nghĩa." },
  { id: "n176", question: "She gave a _____ to each child who participated. (certify)", options: ["certify", "certified", "certifier", "certificate"], correctIndex: 3, explanation: "'Certificate' là danh từ liên quan đến 'certify', nghĩa 'giấy chứng nhận'. Sau mạo từ 'a', câu cần danh từ làm tân ngữ của 'gave'. 'Certified' là tính từ/phân từ (nghĩa 'đã được chứng nhận', mô tả trạng thái) nên không thể đứng sau 'a' ở vị trí danh từ cụ thể như vật được trao tặng." },
  { id: "n177", question: "The company achieved a major _____ last quarter. (break through)", options: ["breakthrough", "breakthrew", "breaking", "broken"], correctIndex: 0, explanation: "'Breakthrough' là danh từ ghép (từ 'break' và 'through'), nghĩa 'bước đột phá', dùng trong cụm 'achieve a breakthrough'. Sau tính từ 'major', câu cần danh từ làm tân ngữ của 'achieved'. 'Breakthrew' không phải một từ đúng trong tiếng Anh (chỉ là cách chia sai của 'break through'), nên chỉ 'breakthrough' mới đúng." },
  { id: "n178", question: "She felt a _____ of excitement when she heard the news. (rush)", options: ["rush", "rusher", "rushing", "rushed"], correctIndex: 0, explanation: "'Rush' vừa là động từ vừa là danh từ (nghĩa 'cơn/luồng cảm xúc bất chợt'), dùng trong cụm 'a rush of excitement'. Sau mạo từ 'a', câu cần danh từ làm tân ngữ của 'felt'. 'Rushing' là tính từ/phân từ (nghĩa 'đang vội vã', mô tả hành động) nên không phù hợp nghĩa và vị trí ở đây." },
  { id: "n179", question: "The _____ of the documentary shed light on the issue. (produce)", options: ["produce", "producer", "producing", "production"], correctIndex: 3, explanation: "'Production' là danh từ của 'produce' (hậu tố '-tion'), ở đây nghĩa 'bộ phim tài liệu được sản xuất', đứng sau 'The' làm chủ ngữ. 'Producer' là danh từ chỉ nhà sản xuất (con người), khác với bản thân tác phẩm 'đã làm sáng tỏ vấn đề' nên không khớp nghĩa câu." },
  { id: "n180", question: "She made a _____ to volunteer at the shelter every week. (resolve)", options: ["resolve", "resolved", "resolver", "resolution"], correctIndex: 3, explanation: "'Resolution' là danh từ của 'resolve' (đổi thành '-tion'), nghĩa 'quyết tâm/lời hứa với bản thân', dùng trong cụm 'make a resolution to'. Sau mạo từ 'a', câu cần danh từ làm tân ngữ của 'made'. 'Resolver' ít dùng và mang nghĩa chủ thể giải quyết vấn đề, không hợp với cụm cố định này." },
  { id: "n181", question: "The _____ of the company to its shareholders is clear. (oblige)", options: ["oblige", "obliged", "obliger", "obligation"], correctIndex: 3, explanation: "'Obligation' là danh từ của 'oblige' (hậu tố '-ation'), dùng trong cụm 'obligation to shareholders'. Sau 'The' làm chủ ngữ, câu cần danh từ. 'Obliged' là tính từ/phân từ (nghĩa 'có nghĩa vụ/biết ơn', mô tả trạng thái của người) nên không thể tự làm chủ ngữ đứng một mình." },
  { id: "n182", question: "Her _____ for justice drove her to become a lawyer. (passionate)", options: ["passionate", "passionately", "passionating", "passion"], correctIndex: 3, explanation: "'Passion' là danh từ gốc (tính từ 'passionate' được tạo từ nó), dùng trong cụm 'passion for justice'. Sau 'Her' làm chủ ngữ, câu cần danh từ. 'Passionately' là trạng từ (hậu tố '-ly') nên không thể làm chủ ngữ đứng sau 'Her' được." },
  { id: "n183", question: "The team showed remarkable _____ under pressure. (resilient)", options: ["resilient", "resiliently", "resilientness", "resilience"], correctIndex: 3, explanation: "'Resilience' là danh từ trừu tượng của tính từ 'resilient' (hậu tố '-ence'), nghĩa 'khả năng phục hồi/chịu đựng'. Sau tính từ 'remarkable', câu cần danh từ làm tân ngữ của 'showed'. 'Resiliently' là trạng từ (hậu tố '-ly') nên không thể đứng ở vị trí danh từ này." },
  { id: "n184", question: "She has a unique _____ to solving complex problems. (approach)", options: ["approach", "approachable", "approaching", "approached"], correctIndex: 0, explanation: "'Approach' vừa là động từ vừa là danh từ (nghĩa 'cách tiếp cận'), dùng trong cụm 'a unique approach to'. Sau tính từ 'unique', câu cần danh từ làm tân ngữ của 'has'. 'Approachable' là tính từ (nghĩa 'dễ gần, dễ tiếp cận', mô tả người) nên không thể đứng sau 'a unique' ở vị trí danh từ này." },
  { id: "n185", question: "The _____ of the experiment provided new insights. (conclude)", options: ["conclude", "concluding", "concluded", "conclusion"], correctIndex: 3, explanation: "'Conclusion' là danh từ của 'conclude' (hậu tố '-sion'), dùng trong cụm 'the conclusion of an experiment'. Sau 'The' làm chủ ngữ, câu cần danh từ. 'Concluding' là tính từ/phân từ (nghĩa 'kết thúc, cuối cùng', như trong 'concluding remarks') nên không thể tự làm chủ ngữ đứng một mình." },
  { id: "n186", question: "He showed no _____ for the feelings of his coworkers. (consider)", options: ["consider", "considerate", "considerably", "consideration"], correctIndex: 3, explanation: "'Consideration' là danh từ của 'consider' (hậu tố '-ation'), dùng trong cụm 'show consideration for'. Sau 'no', câu cần danh từ làm tân ngữ của 'showed'. 'Considerate' là tính từ (nghĩa 'chu đáo, biết quan tâm') nên không thể đứng sau 'no' ở vị trí danh từ này." },
  { id: "n187", question: "There is strong _____ for the new policy among voters. (support)", options: ["support", "supporter", "supporting", "supported"], correctIndex: 0, explanation: "'Support' vừa là động từ vừa là danh từ (nghĩa 'sự ủng hộ'), dùng trong cụm 'strong support for a policy'. Sau tính từ 'strong', câu cần danh từ làm chủ ngữ thực trong cấu trúc 'there is'. 'Supporter' là danh từ chỉ người ủng hộ (con người cụ thể), khác với 'mức độ ủng hộ chung' trong toàn bộ cử tri nên không khớp nghĩa." },
  { id: "n188", question: "The _____ in crime rates is linked to economic inequality. (increase)", options: ["increase", "increasing", "increaser", "increased"], correctIndex: 0, explanation: "'Increase' vừa là động từ vừa là danh từ (nghĩa 'sự gia tăng'), dùng trong cụm 'an increase in crime rates'. Đứng sau 'The' làm chủ ngữ, câu cần danh từ. 'Increasing' là tính từ/phân từ (nghĩa 'đang gia tăng') nên không thể tự làm chủ ngữ đứng sau 'The' được." },
  { id: "n189", question: "She has years of _____ in project management. (experience)", options: ["experience", "experiencing", "experiencer", "experienced"], correctIndex: 0, explanation: "'Experience' là danh từ không đếm được (nghĩa 'kinh nghiệm'), dùng trong cụm 'years of experience'. Sau giới từ 'of', câu cần danh từ. 'Experienced' là tính từ (nghĩa 'có kinh nghiệm', mô tả người, như 'an experienced manager') nên không thể đứng sau 'of' ở vị trí danh từ này." },
  { id: "n190", question: "The _____ of the new policy is still unclear. (imply)", options: ["imply", "implied", "implying", "implication"], correctIndex: 3, explanation: "'Implication' là danh từ của 'imply' (đổi thành '-cation'), nghĩa 'hệ quả/ngụ ý', đứng sau 'The' làm chủ ngữ. 'Implied' là tính từ/phân từ (nghĩa 'được ngụ ý, ám chỉ') nên không thể tự làm chủ ngữ đứng một mình được." },
  { id: "n191", question: "She gave a moving _____ at her grandfather's funeral. (eulogize)", options: ["eulogize", "eulogized", "eulogizing", "eulogy"], correctIndex: 3, explanation: "'Eulogy' là danh từ liên quan đến động từ 'eulogize', nghĩa 'bài điếu văn', dùng trong cụm 'give a eulogy'. Sau tính từ 'moving', câu cần danh từ làm tân ngữ của 'gave'. 'Eulogizing' (V-ing) không tự nhiên bằng danh từ chuẩn 'eulogy' để chỉ bài phát biểu cụ thể tại đám tang." },
  { id: "n192", question: "The _____ between the two models is significant. (differ)", options: ["differ", "different", "differently", "difference"], correctIndex: 3, explanation: "'Difference' là danh từ của 'differ' (hậu tố '-ence'), dùng trong cụm 'difference between models'. Sau 'The' làm chủ ngữ, câu cần danh từ. 'Different' là tính từ (nghĩa 'khác nhau') nên không thể tự làm chủ ngữ đứng sau 'The' được." },
  { id: "n193", question: "She demonstrated great _____ in her negotiations. (flexible)", options: ["flexible", "flexibly", "flex", "flexibility"], correctIndex: 3, explanation: "'Flexibility' là danh từ của tính từ 'flexible' (hậu tố '-ility'), nghĩa 'sự linh hoạt'. Sau tính từ 'great', câu cần danh từ làm tân ngữ của 'demonstrated'. 'Flexibly' là trạng từ (hậu tố '-ly') nên không thể đứng ở vị trí danh từ sau 'great' này." },
  { id: "n194", question: "The _____ of basic necessities is a human right. (access)", options: ["access", "accessing", "accessible", "accessibility"], correctIndex: 0, explanation: "'Access' vừa là động từ vừa là danh từ (nghĩa 'quyền/khả năng tiếp cận'), dùng trong cụm 'access to basic necessities'. Đứng sau 'The' làm chủ ngữ, câu cần danh từ. 'Accessible' là tính từ (nghĩa 'có thể tiếp cận được') nên không thể tự làm chủ ngữ đứng sau 'The' được." },
  { id: "n195", question: "She has demonstrated a clear _____ of leadership. (able)", options: ["able", "ability", "ably", "enablement"], correctIndex: 1, explanation: "'Ability' là danh từ của tính từ 'able' (hậu tố '-ity'), dùng trong cụm 'demonstrate an ability of'. Sau tính từ 'clear', câu cần danh từ làm tân ngữ của 'has demonstrated'. 'Ably' là trạng từ (hậu tố '-ly') nên không thể đứng sau 'a clear' ở vị trí danh từ này." },
  { id: "n196", question: "The _____ of the new law is expected to be significant. (impact)", options: ["impact", "impactful", "impactfully", "impaction"], correctIndex: 0, explanation: "'Impact' vừa là động từ vừa là danh từ (nghĩa 'tác động/ảnh hưởng'), dùng trong cụm 'the impact of a law'. Đứng sau 'The' làm chủ ngữ, câu cần danh từ. 'Impactful' là tính từ (hậu tố '-ful', nghĩa 'có tác động mạnh') nên không thể tự làm chủ ngữ đứng sau 'The' được." },
  { id: "n197", question: "Her _____ of the data was thorough and detailed. (examine)", options: ["examine", "examiner", "examined", "examination"], correctIndex: 3, explanation: "'Examination' là danh từ của 'examine' (hậu tố '-ation'), dùng trong cụm 'examination of data'. Sau 'Her' làm chủ ngữ, câu cần danh từ. 'Examiner' là danh từ chỉ người kiểm tra/giám khảo (con người), không phải bản thân việc xem xét dữ liệu 'kỹ lưỡng và chi tiết' nên không khớp nghĩa." },
  { id: "n198", question: "The _____ of the new manager boosted team morale. (arrive)", options: ["arrive", "arrived", "arriving", "arrival"], correctIndex: 3, explanation: "'Arrival' là danh từ của 'arrive' (hậu tố '-al'), nghĩa 'sự đến/xuất hiện', dùng trong cụm 'the arrival of a manager'. Sau 'The' làm chủ ngữ, câu cần danh từ. 'Arriving' là tính từ/phân từ (nghĩa 'đang đến') nên không thể tự làm chủ ngữ đứng một mình ở đây." },
  { id: "n199", question: "She has a natural _____ for connecting with people. (gift)", options: ["gift", "gifted", "giftedly", "giftedness"], correctIndex: 0, explanation: "'Gift' là danh từ (nghĩa 'năng khiếu, tài năng bẩm sinh'), dùng trong cụm 'a natural gift for'. Sau tính từ 'natural', câu cần danh từ làm tân ngữ của 'has'. 'Gifted' là tính từ (nghĩa 'có năng khiếu', mô tả người) nên không thể đứng sau 'a natural' ở vị trí danh từ này." },
  { id: "n200", question: "The _____ of the research was published in Nature journal. (find)", options: ["find", "finding", "found", "findings"], correctIndex: 3, explanation: "'Findings' (số nhiều, hậu tố '-ings') là danh từ của 'find', nghĩa 'kết quả nghiên cứu', đứng sau 'The' làm chủ ngữ - dạng số nhiều này là cách dùng chuẩn khi nói về kết quả nghiên cứu được công bố. 'Finding' (số ít) ít tự nhiên hơn trong ngữ cảnh học thuật này, còn 'found' chỉ là dạng quá khứ của động từ 'find', không thể làm danh từ chủ ngữ." },
];
